programs.sol:
"""Approximate local responses to continuations of dash markers.

Conjunctions after attached hyphens ("pre- and post-", "In- und Ausland")
produce positive pulses, with weaker responses after spaced dashes.
Alphabetic command-option starts after -- produce negative pulses scaled
by name length and quoting; no/help/version/dry get stronger pulses.
Several diff, test, table, citation, path and ASCII-rule continuations get
fixed smaller responses. Unmatched positions return zero: the small,
context-dependent background activation is not modeled.
"""
READS = ()

# Closed-class conjunctions used in suspended compound constructions.
STRONG_AND = {'und', 'och', 'og', 'és'}
ALTERNATIVES = {'oder', 'eller'}


def step(carry, prefix, upstream):
    i = prefix.position
    t = prefix.token_strings[-1]
    if i == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    prev = prefix.token_strings[-2]
    earlier = ''
    if i > 1 and prefix.document_ids[-1] == prefix.document_ids[-3]:
        earlier = prefix.token_strings[-3]
    value = 0.0
    word = t.strip()

    if prev in {'-', ' -'} and t.startswith(' '):
        if word in STRONG_AND:
            value = 14.8 if prev == '-' else 4.3
        elif word in ALTERNATIVES:
            value = 9.5 if prev == '-' else 1.5
        elif word in {'and', 'or'}:
            value = 8.0 if prev == '-' else 1.0
        elif word in {'и', 'или'}:
            value = 6.0 if prev == '-' else 1.0
        elif word in {'to', 'als'}:
            value = 3.8 if prev == '-' else 0.5

    if prev == '-' and not earlier[-1:].isalnum() and value > 0:
        value *= 0.2

    # A whitespace-delimited or quoted option introducer, not a prose dash.
    flag = prev in {' --', ' "--', " '--"}
    quoted = prev == '--' and earlier.rstrip().endswith(('"', "'", '`'))
    if (flag or quoted) and t[:1].isascii() and t[:1].isalpha():
        size = 2.0 if len(t) == 1 else 4.5 if len(t) == 2 else 6.8
        if t in {'no', 'help', 'version', 'dry'}:
            size = 10.5
        if prev == " '--":
            size *= 0.55
        elif prev == '--':
            size *= 0.45
        elif prev == ' "--':
            size *= 0.85
        value = -size

    marker = prev.lstrip(' ')
    if marker and set(marker) == {'-'}:
        if len(marker) == 3 and t == ' PASS':
            value = 3.6
        elif len(marker) == 3 and t == ' FAIL':
            value = 1.0
        elif len(marker) == 3 and t == ' a':
            value = 2.0
        elif len(marker) >= 3 and t.startswith(' |'):
            value = 2.5
        elif len(marker) == 2 and t == ' /':
            value = 3.5
        elif len(marker) == 2 and t.startswith(('@', '[@')):
            value = 2.0

    # Ends of long ASCII progress bars / decorative rules.
    if len(marker) >= 4 and set(marker) == {'='}:
        if '>' in t:
            value = -3.5
        elif t.startswith('=') and '"' in t:
            value = -2.8
    return None, value

programs.haiku:
"""layers.1.mlp.down_proj:196 -- "the type of a declaration is complete; a name comes next".

It fires on the last token of a type in a declaration in C-like code (Java, C#, C++, C),
where the next token should be a variable or parameter name:
  - the '>' that closes a generic type: `List<String>` in `private List<String> links`
  - a reference, pointer or array marker after a type: `const RGB &_color`, `double *r`, `String[] args`
  - a C type suffix: `size_t` / `Double_t` followed by the name
It stays near 0 on prose, HTML, comparisons and calls such as `new List<X>()`. Values are
GENERIC_VALUE for a closing '>', POINTER_VALUE for a reference, pointer or array marker, and
SUFFIX_VALUE for a '_t' suffix; the rest of the time it predicts 0.
"""
import re

READS = ()

KEYWORDS = {"const", "static", "public", "private", "protected", "final", "struct", "unsigned", "for"}
NOT_TYPES = {"return", "new", "throw", "else", "extends", "implements", "if", "while", "case", "as", "in", "is"}
TYPE_WORDS = {"int", "char", "float", "double", "void", "bool", "boolean", "byte", "long", "short",
              "string", "String", "unsigned", "size_t"}
PIECE = re.compile(r"\w+(?:::\w+)*|\[\]|\.\.\.|->|&&|\|\||\S")
WORD = re.compile(r"\w+(?:::\w+)*")
GENERIC_VALUE, POINTER_VALUE, SUFFIX_VALUE = 7.0, 5.0, 2.0


def is_type(word):
    """A capitalised class name (List, Map, RGB), a C/Java primitive, or a *_t typedef."""
    return bool(re.fullmatch(r"[A-Z]\w*", word)) or word in TYPE_WORDS or word.endswith("_t")


def in_declaration(recent, in_params):
    """Does the type ending `recent` open a declaration? Looks back past a few words of the same statement."""
    j, words = len(recent) - 2, 0
    while j >= 0:
        token = recent[j]
        if token in KEYWORDS or token in (";", "{", "}"):
            return True
        if token in ("(", ","):
            return in_params
        if token in NOT_TYPES or words >= 3 or not WORD.fullmatch(token):
            return False
        words += 1
        j -= 1
    return True


def step(carry, prefix, upstream):
    # generics: one flag per open '<', True if it opens a declared type
    # parens: one flag per open '(', True if it is a parameter list or a for-header
    # recent: the last few pieces of text, so the context of the current piece can be read
    stack, parens, recent, doc = carry if carry is not None else ([], [], [], None)
    if prefix.document_ids[-1] != doc:
        stack, parens, recent = [], [], []
    value = 0.0
    raw = prefix.token_strings[-1]
    if "\n" in raw:
        stack = []
    for piece in PIECE.findall(raw):
        in_params = bool(parens) and parens[-1]
        typed = bool(recent) and is_type(recent[-1])
        if piece == "<" and typed:
            nested = len(recent) > 1 and recent[-2] == "<" and bool(stack) and stack[-1]
            stack.append(in_declaration(recent, in_params) or nested)
        elif piece == ">" and stack:
            if stack.pop():
                value = GENERIC_VALUE
        elif piece in ("*", "&", "[]") and typed and in_declaration(recent, in_params):
            value = POINTER_VALUE
        elif piece == "_t" and recent and in_declaration(recent, in_params):
            value = SUFFIX_VALUE
        elif piece == "(":
            parens.append(bool(recent) and bool(WORD.fullmatch(recent[-1])) or recent[-1:] == ["for"])
        elif piece == ")" and parens:
            parens.pop()
        elif piece in (";", "{", "}"):
            stack = []
        recent = (recent + [piece])[-8:]
    return (stack, parens, recent, prefix.document_ids[-1]), value

"""Layer-1 MLP unit 199 (down_proj): a 'phrase-head noun' detector.

The unit dips negative on a noun that heads a fixed prepositional phrase of manner, form,
degree, place or scope: 'in [a] [way] that', 'in such a [way]', 'in the [form] of',
'in the [manner] of', 'to an [extent]', 'in the [sense] of', 'at a [rate]', 'in [terms] of',
'for [purposes]', 'at [times]', 'in the [area] of', 'in the [position] of'. The dip is
deepest after 'a' and 'such a', weaker after 'the', and close to zero after 'this', 'that',
'some' and 'each'. The same manner words in other languages ('manière', 'façon', 'forma',
'caso', 'modo') dip too. A few text-part nouns after 'in the' ('statement', 'comments',
'introduction', 'following') go slightly positive. 'than' dips weakly unless it follows
'more', 'less', 'rather', 'better' or 'greater'. Everywhere else it stays near zero."""

READS = ()

# Manner and form nouns: the strongest dip.
TIER1 = {"form", "forms", "manner", "manners", "extent", "style", "sense", "rate", "way", "ways",
         "manière", "façon", "forma", "caso", "modo", "manera"}
# Degree, scope, purpose and cause nouns.
TIER2 = {"direction", "purpose", "purposes", "level", "basis", "scale", "context", "scope",
         "degree", "age", "fashion", "perspective", "meaning", "reason", "reasons", "framework",
         "shape", "cost", "speed", "respect", "terms", "mode", "cases", "format", "expense",
         "situation", "situations", "circumstances", "order", "point"}
# Place, position, time and state nouns: a weaker dip.
TIER3 = {"case", "area", "areas", "region", "regions", "location", "locations", "position",
         "positions", "place", "places", "space", "side", "sides", "grounds", "hands", "state",
         "zone", "territory", "time", "times", "date", "period", "periods", "year", "years",
         "days", "lieu", "vicinity"}
# Text-part nouns that go slightly positive after 'in the'.
POSITIVE = {"statement", "comments", "introduction", "following", "editor", "text", "word",
            "words", "evidence", "plane", "main", "back"}
# How strongly each determiner, after a preposition, passes the dip on to the noun.
DETERMINER = {"a": 1.0, "an": 1.0, "such": 1.0, "the": 0.5, "some": 0.2, "one": 0.2,
              "this": 0.1, "that": 0.1, "each": 0.0, "every": 0.0}
BASE = {1: -7.0, 2: -2.5, 3: -2.0}
PREPS = {"in", "at", "to", "for", "on", "within", "into", "under", "from"}
BARE_PREPS = {"in", "at", "for"}   # 'in terms', 'in ways', 'for purposes', 'at times'


def word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    n = len(toks)
    cur = word(toks[-1])
    if n < 3 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    p1 = word(toks[-2])
    p2 = word(toks[-3])
    # Weak generic dip on 'than' (comparatives such as 'closer ... than', 'longer than').
    if cur == "than" and p1 not in ("more", "less", "rather", "better", "greater"):
        return None, -0.3
    if cur in TIER1 or cur in TIER2 or cur in TIER3:
        tier = 1 if cur in TIER1 else 2 if cur in TIER2 else 3
    elif cur in POSITIVE:
        return None, (1.0 if p1 in DETERMINER and p2 in PREPS else 0.0)
    else:
        return None, 0.0
    # Manner words in other languages dip regardless of the words before them.
    if cur in ("manière", "façon", "forma", "caso", "modo", "manera"):
        return None, -2.0
    # Plural nouns right after 'in', 'at' or 'for' with no determiner: 'in ways', 'in terms'.
    if p1 in BARE_PREPS and cur.endswith("s"):
        return None, 0.75 * BASE[tier]
    if p1 in DETERMINER and p2 in PREPS:
        return None, DETERMINER[p1] * BASE[tier]
    if p1 in DETERMINER and p2 == "such" and n > 3 and word(toks[-4]) in PREPS:
        return None, BASE[tier]
    return None, 0.0

programs.sol:
"""A sparse spelling-and-formatting approximation, not a general semantic feature.

Large responses occur on Bulgarian hard signs, Romanian inflection fragments,
and some vowel signs completed by isolated UTF-8 bytes. Recent completed words'
corpus frequencies gate the Romanian rules. Code-listing headers and middle-dot
leaders have separate formatting rules. Most other tokens return zero; many
small, context-dependent native responses are deliberately left unexplained.
"""
import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

# Russian prefix-final hard signs separate consonants from iotated vowels;
# they are not the Bulgarian vowel that this rule aims to detect.
RUSSIAN_PREFIXES = set(
    'об под над пред от раз из без меж сверх суб'.split()
)
ROMANIAN_INFINITIVES = {'are', 'ere', 'ire'}
ROMANIAN_PARTICIPLES = set('at ut it ata ate uta ute ita ite ată'.split())
ROMANIAN_NOUN_ENDINGS = set('ie ii uri ți ţi ț ţ'.split())
ROMANIAN_PRESENT_ENDINGS = {'esc', 'asc', 'ază', 'ze'}


@lru_cache(maxsize=100000)
def romanian_evidence(word):
    """A frequency advantage over neighboring Latin-script languages."""
    if len(word) < 4 or 'LATIN' not in unicodedata.name(word[0], ''):
        return None
    ro = zipf_frequency(word, 'ro')
    if ro < 3:
        return -1.0
    rivals = ('en', 'fr', 'it', 'es', 'de', 'pt', 'hu', 'pl', 'vi')
    other = max(zipf_frequency(word, lang) for lang in rivals)
    return max(-1.0, min(2.0, ro - other))


# Names of Hebrew points, not tokenizer-specific token IDs.
HEBREW_POINTS = {
    'SEGOL': 5.8,
    'QAMATS': 5.4,
    'PATAH': 2.8,
    'HIRIQ': 2.6,
    'DAGESH OR MAPIQ': 4.3,
    'SHEVA': -1.2,
}


def split_character_value(ch, text):
    """Some vowel signs are conspicuous when their UTF-8 is split into tokens."""
    name = unicodedata.name(ch, '')
    if name == 'HEBREW POINT DAGESH OR MAPIQ':
        base = next((c for c in reversed(text[:-1]) if c.isalpha()), '')
        if base == 'ו':  # On vav, this dot is the vowel shuruq instead.
            return 0.4
    if name.startswith('HEBREW POINT '):
        return HEBREW_POINTS.get(name.removeprefix('HEBREW POINT '), 0.0)
    if name.startswith('SINHALA VOWEL SIGN '):
        return 4.0
    if name.startswith('TAMIL VOWEL SIGN '):
        return 2.3 if name.endswith(' II') else 0.9
    if name.startswith('TELUGU VOWEL SIGN '):
        return 1.0
    if name == 'THAI CHARACTER MAI TRI':
        return 0.7
    if 'LETTER' in name and 'DOUBLE ACUTE' in name:
        return 0.8
    if name.startswith('HIRAGANA LETTER P'):
        return 1.2
    if name.startswith('HANGUL SYLLABLE '):
        syllable = ord(ch) - 0xAC00
        vowel, coda = (syllable % 588) // 28, syllable % 28
        if vowel == 18 and coda in (4, 8):  # eu vowel, final n or l
            return 4.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, line, byte_tail, word, ro, bg = '', '', b'', '', 0.0, 0.0
    else:
        _, recent, line, byte_tail, word, ro, bg = carry
    s, b = prefix.token_strings[-1], prefix.token_bytes[-1]
    before = word
    if s.startswith('<|'):
        word, ro, bg = '', 0.0, 0.0
    for ch in s:
        if ch.isalpha():
            word = (word + ch.lower())[-60:]
            if ch in 'șțţ' or s == 'ă':
                ro = max(ro, 0.9)
        else:
            if word:
                evidence = romanian_evidence(word)
                if evidence is not None:
                    ro = 0.85 * ro + 0.15 * evidence
            word = ''

    value = 0.0
    w = s.strip().lower()
    # Word fragments in likely Romanian text.
    if (ro > 0.35 and w and w.isalpha()
            and 'LATIN' in unicodedata.name(w[0], '')):
        if not s[0].isspace():
            value = -0.12 if any(c in 'mn' for c in w) else -0.45
            if w in ROMANIAN_INFINITIVES:
                value = -1.6
            elif w in ROMANIAN_PARTICIPLES:
                value = -1.0
            elif w in ROMANIAN_NOUN_ENDINGS:
                value = -1.0
            elif w in ROMANIAN_PRESENT_ENDINGS:
                value = -1.8
        else:
            value = -0.15

    # These three Russian letters are absent from Bulgarian spelling.
    russian = (s == 'ъ' and (before in RUSSIAN_PREFIXES
                            or any(c in recent for c in 'ыэё')))
    if s == 'ъ' and not russian:
        bg = 1.0
        value = 4.7 if before.endswith(('т', 'д')) else 2.9
        if before.endswith('в'):
            value = 3.7
    elif s == 'ъ':
        value = -0.1
    elif bg > 0.15 and w and 'CYRILLIC' in unicodedata.name(w[0], ''):
        if recent.endswith('ъ') and s in ('л', 'р'):
            value = 1.5
        elif not s[0].isspace():
            value = -0.45 if w.endswith(('а', 'я', 'е', 'и')) else -0.05
            if w in ('ени', 'ете', 'ва', 'ни'):
                value = -1.3
        elif w == 'да':
            value = 0.9
        elif w == 'за':
            value = -1.0
    if s == 'ă':
        value = -1.7

    # Detached UTF-8 tails need the preceding bytes to identify a vowel sign.
    joined = byte_tail + b
    text = joined.decode('utf-8', 'replace')
    ch = text[-1:]
    if ch and len(b) == 1 and 0x80 <= b[0] < 0xC0:
        value = split_character_value(ch, text)
    if s == '으':
        value = -0.6
    # Repeated leaders and the first padding after a code-listing header.
    if len(s) >= 2 and not s.strip('·'):
        value = 3.35
    if s and not s.strip(' ') and not line:
        previous_line = recent.rsplit('\n', 2)[-2] if recent.endswith('\n') else ''
        if previous_line.endswith(':'):
            if 'cat -n' in previous_line or re.search(r'/[^\n ]+:$', previous_line):
                value = -0.44
    recent = (recent + s)[-400:]
    line = (line + s).rsplit('\n', 1)[-1][-150:]
    return (doc, recent, line, joined[-8:], word, ro, bg * 0.985), value

"""A sparse recognizer for document openings and scholarly citation syntax.

Large positive responses mark some code-declaration openers, source metadata
fields, and the colon in a document-initial 'Title:' header. Python function
and docstring openings, and initial empty-string entries, are negative. The 'al' in 'et al.' has a
smaller positive response. Space-prefixed opening tokens get a mild negative
baseline. Other text is zero; most small activations remain unexplained.
"""

READS = ()
SOURCE_FIELDS = ('<filename', '<reponame', '<gh_stars')
DECLARATIONS = {'using', 'import', 'export', 'class'}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        position, tail, previous = 0, '', ''
    else:
        _, position, tail, previous = carry
    tail = (tail + token)[-40:]

    value = 0.0
    if position == 0:
        if token.startswith(' ') and token.strip():
            value = -0.08
        if token == 'namespace':
            value = 2.066
        elif token in DECLARATIONS:
            value = 0.68
        elif token == 'const':
            value = 1.32
        elif token == 'def':
            value = -0.92
        elif token.strip() in {'"""', "'''"}:
            value = -0.71
        elif token.strip() == "'',":
            value = -1.388
        elif token == '<':
            value = 0.293
    elif position == 1 and previous == 'Title' and token == ':':
        value = 3.408
    elif previous.strip() == 'et' and token == ' al':
        value = 0.35
    elif position < 40 and tail.endswith(SOURCE_FIELDS):
        # Later fields in a source header have weaker responses.
        value = 1.26 / (1.0 + 0.045 * max(0, position - 3))

    return (document, position + 1, tail, token), value

"""A sparse detector of serialized source-code headers and opening formatting.

Repository names, filenames and GitHub star-count tags produce strong negative
values while their names are spelled. The first field is stronger than later
fields on the same header line. Issue-thread markers are smaller negative
cues. Unbroken opening runs of spaced periods, middle dots or escaped tabs
are positive. Other positions, including ordinary lexical responses, are zero.
"""

READS = ()

# Cumulative spellings of the three source-code metadata field names.
OPENING_FIELDS = {
    '<re': -11.08,
    '<repon': -6.33,
    '<reponame': -37.31,
    '<reponame>': -0.62,
    '<filename': -51.36,
    '<filename>': -8.49,
    '<filename>_': -1.24,
    '<gh': -14.60,
    '<gh_st': -5.50,
    '<gh_stars': -39.60,
    '<gh_stars>': -4.47,
}
LATER_FIELDS = {
    '<filename': -44.0,
    '<filename>': -4.3,
    '<gh': -12.0,
    '<gh_st': -1.7,
    '<gh_stars': -23.0,
    '<gh_stars>': -2.7,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        tail, count, first, uniform, header = b'', 0, token, True, False
    else:
        _, tail, count, first, uniform, header = carry
    uniform = uniform and token == first
    tail = (tail + prefix.token_bytes[-1])[-160:]
    count += 1
    text = tail.decode('utf-8', errors='replace')
    header = header or text in ('<reponame', '<filename', '<gh_stars')
    if b'\n' in prefix.token_bytes[-1]:
        header = False
    state = doc, tail, count, first, uniform, header

    if text in OPENING_FIELDS:
        return state, OPENING_FIELDS[text]
    if header:
        for ending, value in LATER_FIELDS.items():
            if text.endswith(ending):
                return state, value

    value = 0.0
    if uniform:
        if token == ' .':
            value = 3.66
        elif token == '··':
            value = 1.79
        elif token == r'\t':
            value = 1.70
    if text == '<':
        value = 0.39

    # The related issue-thread serialization tags.
    if text.endswith('<issue'):
        value = -9.2 if count <= 5 else -0.3
    elif text.endswith('<issue_closed'):
        value = -2.5
    elif text.endswith('<issue_comment'):
        value = -0.66 if count <= 6 else -0.30
    elif text.endswith('<issue_start'):
        value = -1.77
    elif text.endswith('<issue_start><'):
        value = -2.24
    return state, value

"""A selective ch-spelling detector; unmatched tokens predict zero.

Beach/coach/couch families and several short ch fragments are negative;
y-ch and psych fragments are positive. The spelling left of a fragment,
capitalization, and whether a word is split across tokens affect its value.
Common whole words like 'which' and 'approach' do not trigger the rule.
There are small matching rules for ch-like letters in other scripts,
Vietnamese cách, and pairs of middle dots. State retains a word tail and
the previous token, resetting when the document changes.
"""
import re
from anyascii import anyascii

READS = ()


def fragment_value(fragment, before):
    """Short ch spellings: rounded/long vowels negative, y/psych positive."""
    stem = before + fragment[:fragment.find('ch')]
    if before.endswith('psy') or (fragment.startswith('ych')
                                 and before.endswith('ps')):
        return 4.2
    if stem.endswith(('bou', 'dou', 'cou')):
        return -6.0
    if stem.endswith(('bea', 'bee', 'pea', 'coa', 'broo', 'poo')):
        return -6.5
    if stem.endswith('au'):
        return -3.8
    if before.endswith(('cl', 'c', 'co', 'cro')):
        return -3.0
    if fragment.startswith('ouch'):
        return -0.5 if before.endswith('t') else -5.2
    if fragment.startswith('ych') or before.endswith('y'):
        return 2.2
    if before.endswith(('yl', 'syn')):
        return 2.8
    if fragment.startswith('ich'):
        return -2.8 if before.endswith('ch') else 0.0
    if fragment.startswith('ach'):
        if before.endswith('e'):
            return 0.0 if before.endswith(('re', 'te')) else -1.8
        return 1.5 if before.endswith('t') else 0.6
    if fragment.startswith('ch'):
        if before.endswith('o'):
            return -2.3
        if before.endswith(('cin', 'con', 'col')):
            return -1.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    oldword, previous = ('', '')
    if carry is not None and carry[0] == doc:
        oldword, previous = carry[1:]
    text = prefix.token_strings[-1]
    # Recover a character completed by a byte-fragment token.
    if '\ufffd' in text:
        raw = prefix.token_bytes[-1]
        prior = b''
        if len(prefix.document_ids) > 1 and prefix.document_ids[-2] == doc:
            prior = prefix.token_bytes[-2]
        complete = (prior + raw).decode('utf-8', 'ignore')
        text = complete[len(prior.decode('utf-8', 'ignore')):]
    word = text.strip().lower()
    match = re.search(r'[^\W\d_]+$', oldword + text)
    tail = match.group()[-32:] if match else ''
    value = 0.0

    # Lexical ch families, with their ordinary English inflections.
    m = re.fullmatch(r'(beach|coach|couch|pouch|peach)(es|ed|ing)?', word)
