Short od/од fragments and o|d token joins give positive responses, especially
in nod/rod sequences. Whole familiar words respond much less. The response
can linger for two continuation tokens. Transliteration shares these rules
across Latin, Cyrillic and Greek spelling. Constants summarize training data;
they do not capture every lexical exception or the full strength of spikes.
"""
import re
from functools import lru_cache
import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
EAST_ASIAN = regex.compile(r'[\p{Han}\p{Hiragana}\p{Katakana}\p{Hangul}\uFFFD]')


@lru_cache(maxsize=30000)
def spelling(text):
    return anyascii(text).lower()


@lru_cache(maxsize=30000)
def familiarity(text):
    return zipf_frequency(text.lower(), 'en')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, word, age = '', '', 9
    else:
        _, previous, word, age = carry
    token = prefix.token_strings[-1]
    if EAST_ASIAN.search(token):
        return (doc, token, '', 9), 0.0

    s, p = spelling(token), spelling(previous)
    pieces = re.split(r'[\W_]+', token)
    word = (word + token)[-60:] if len(pieces) == 1 else pieces[-1][-60:]
    w = spelling(word)
    own = 'od' in s
    cross = p.endswith('o') and s.startswith('d')
    age = 0 if own or cross else age + 1
    at = w.rfind('od')
    after = len(w) - at - 2 if at >= 0 else 99
    near = at >= 0 and age <= 2 and after <= 12
    reverse = p.endswith('d') and (s.startswith('o') or s.startswith('ro'))
    state = (doc, token, word, age)
    if not (own or cross or near or reverse):
        return state, 0.0

    before = w[at - 1] if at > 0 else ''
    length = len(s.strip())
    boundary = not token[:1].isalpha()
    clean = ''.join(c for c in token if c.isalpha())
    frequency = familiarity(clean)

    # A fresh fragment, with its left-hand spelling context.
    if s.startswith('od'):
        if before == 'n':
            value = 7.2 if familiarity(previous.strip()) <= 3.8 else 2.5
        elif before == 'r':
            value = 3.85
        elif before == 'c':
            value = -0.9
        elif before == 'l':
            value = 3.15
        else:
            value = 1.4
    # The o and d can lie on opposite sides of a token boundary.
    elif cross:
        if length <= 3:
            value = 5.7 if before == 'r' else 2.4
        else:
            value = 1.5 if before == 'r' else 0.05
    elif s.strip(' /.-_') == 'node':
        if s.startswith('/'):
            value = 2.75
        else:
            value = 1.6 if s.startswith('-') else 0.85
    elif own and length <= 5 and frequency < 4:
        if s == 'mod' and p.endswith('s'):
            value = 5.8
        elif before == 'r':
            value = 0.8 if boundary else 2.7
        else:
            value = 0.5 if frequency > 1.8 else 0.0
    elif reverse:
        # od|ro continues the fragment; plain d|o is much weaker.
        value = 2.25 if near and s.startswith('ro') else 0.1
    elif near and not own and not cross:
        # A small echo on letters continuing an unfinished word.
        if p.endswith('d'):
            value = 1.9 if frequency > 6 else 0.45
        else:
            value = 0.1
    elif before == 'c':
        value = -0.07
    else:
        value = 0.2 if length <= 4 else 0.05
    return state, value

