VOWELS = set('aeiouyаеёиоуыэюяαεηιουω')
STOPS = set('bptdkgбптдкг')

@lru_cache(30000)
def spelling(t):
    t = ''.join(c for c in unicodedata.normalize('NFD', t.lower())
                if not unicodedata.combining(c))
    leading = 0
    for c in t:
        if not consonant(c):
            break
        leading += 1
    trailing = 0
    for c in reversed(t):
        if not consonant(c):
            break
        trailing += 1
    return t, leading, trailing, sum(c in VOWELS for c in t)

@lru_cache(2000)
def consonant(c):
    return bool(c and c.isalpha() and c not in VOWELS and
                any(s in unicodedata.name(c, '')
                    for s in ('LATIN', 'CYRILLIC', 'GREEK')))


