    t = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    same = carry is not None and carry[0] == doc
    previous = carry[1] if same else ''
    position = carry[2] + 1 if same else 0
    a, _, trailing, vowels = spelling(previous)
    b, leading, _, _ = spelling(t)
    value = -0.011 if b[:1].isalpha() else -0.0014
    if trailing and leading:
        if t[:1].isupper():
            value = 0.314 if previous[-1:].isupper() and vowels else -0.0072
        elif not vowels:
            value = -0.025 if previous[-1:].isupper() else 0.158
        elif len(t) > 3:
            value = 0.13
        elif trailing == 1:
            value = 0.448 if not any(c in VOWELS for c in b) else 0.263
        elif b[0] not in STOPS:
            value = 0.218 if b[0] in 'lrлр' else 0.513
        elif a[-1] not in STOPS:
            value = 0.621
        else:
            value = 0.836 if previous[:1].isspace() else 1.56
    if position == 0 and t == 'Title':
        value = 0.595
    if position == 1 and previous == 'Title' and t == ':':
        value = 5.671
    return (doc, t, position), value

