    s = s.translate(str.maketrans({'خ': 'x', 'ظ': 'z', 'ذ': 'd', 'غ': 'g'}))
    s = s.replace('ж', 'j').replace('Ж', 'J')
    s = s.replace('ч', 'q').replace('Ч', 'Q')
