        return -3.8 if boundary else -5.5
    if w.startswith('harr') and len(w) <= 6:
        return -1.0 if w.endswith('y') else -3.1
    if w in ('hash', 'hashed', 'hashes', 'hashing', 'harsh', 'shard', 'shards'):
