        return 0.15 if s in {'0', '9'} else 3.3
    if set(s) == {'#'}:
        return 7.8 - 0.3 * len(s) if len(s) <= 3 else 3.6
    if word == '-':
        return 8.25 if s == word else 5.8
    if set(word) == {'-'}:
        return 4.0 if len(word) == 2 else 2.0
    if set(word) <= {'·', '・'}:
        return 5.5
