        return 5.4
    if word in {'**', '__'}:
        return 7.5 if word == '**' else 4.8
    if word in {'•', '*'}:
        return 3.5
    if word in {'–', '—'}:
        return 4.0
    if word in {'and', 'or'}:
        return 3.8
    if s in {'package', 'import', 'from'}:
        return 4.7
    if '\n' in s or '\r' in s:
        return -0.35
    if set(s) == {'^'} and len(s) > 1:
        return -2.3
    if word in {'"', "'", '|', '“', '「', '【', ']'}:
        return 2.0
    if s == 'Title':
        return -1.06
    if s == ':':
        return 3.3
    if all(not c.isalnum() for c in s) and s[0] in '.);^/':
