READS = ()
"""Layer-1 MLP component 212 (down_proj): a document-start detector.

It is almost silent except on the first token of a document. Positions restart at each
document, so that token has no earlier context and its value depends only on which token
it is. There, list, heading and comment markers (#, ##, -, **, •) push it up strongly;
code comment openers (//, /*, and the triple-quote docstring marker) push it up strongly
too; digits 1-8 push it up moderately; and a few code words and punctuation starts
(package, import, from, and, or, '.', ':', ')', '&', '/', '|', ']') push it up less.
The one large spike is the ':' of a 'Title:' header at the start of a document.
Everything else predicts 0.
"""

HEADING_OR_LIST = {"#", "##", "###", "####", "-", " -", "–", "—", "•", "*", "**", "-*-"}
COMMENT_OPENERS = {"//", "/*", "/*\n", "/*\r\n", "//\n", "/**\n", '"""\n', "'''\n"}
CODE_WORDS = {"package", "import", "from", "export", "def"}
PUNCTUATION_STARTS = {
    " and", " or", ".", ":", ")", "]", "&", " &", "/", " *", "|", " |", "#!/",
    "<|endoftext|>",
}
DIGITS_1_TO_8 = set("12345678")


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    if prefix.position > 0 and docs[-1] == docs[-2]:
        # Not a document's first token. Only the 'Title:' spike, at document position 1.
        title_first = prefix.position == 1 or docs[-3] != docs[-2]
        if title_first and toks[-2] == "Title" and toks[-1] == ":":
            return None, 13.3
        return None, 0.0
    tok = toks[-1]
    if tok in HEADING_OR_LIST:
        return None, 7.0
    if tok in COMMENT_OPENERS:
        return None, 6.0
    if tok in CODE_WORDS:
        return None, 4.5
    if tok in PUNCTUATION_STARTS:
        return None, 3.0
    if tok in DIGITS_1_TO_8:
        return None, 3.3
    return None, 0.0

