import re

READS = ()
VERSION_CUE = re.compile(
    r'(?<![a-z])version|python|phpunit|pytest|gcc|nodejs|npm|rustc|'
    r'\bjava\b|ruby|openapi|semver|mime|apache|\brelease\b|compatib|'
    r'specification|@since|dependencies|'
    r'\b(?:PHP|KDE|HTTP|Mozilla|Ubuntu|Slackware|Go|Perl|MPI|Django)\b',
    re.I,
)
