def number_response(before, number, token):
    parts = number.split('.')
    sections = len(parts) - 1
    digit = token != '.'
    v_prefix = bool(re.search(r'(?<![A-Za-z])[vV]$', before))
    requirement = before.endswith(('^', '~', '>=', '<=', '=='))
    package = bool(re.search(r'[A-Za-z][\w.-]*[@/-]$', before))
    if not sections:
        return 0.25 if v_prefix else 0.0
    # Later digits in a section are much less informative than its first.
    if digit and len(parts[-1]) > 1:
        return 0.04
    cues = list(VERSION_CUE.finditer(before))
    distance = len(before) - cues[-1].end() if cues else 10000
    glued = before.rsplit(' ', 1)[-1].rsplit('\n', 1)[-1]
    path = '/' in glued and len(glued) > 2
    if before.endswith('__'):
        return 1.91 if digit else 0.53
    if int(parts[0]) >= 100:
        return 0.04
    direct = before[-24:].lower()
    if re.search(r'http/\s*$', direct):
        return 1.4 if digit else 0.5
    if re.search(r'(?<![a-z])(?:version|python|@since)[^\w]{0,7}$', direct):
        strength = 2.6 if 'version' in direct else 2.4
        if 'apache license' in before[-60:].lower():
            strength = 3.6
        return strength if digit else 0.8
    if requirement or (package and path):
        return 1.95 if digit else 0.70
    if sections >= 2:
        if distance <= 240 or v_prefix:
            return 2.43 if digit else 1.38
        return (1.29 if int(token) <= 1 else 0.75) if digit else 0.48
    if v_prefix:
        return 1.77 if digit else 0.88
    if distance <= 24:
        return 1.77 if digit else 0.63
    if distance <= 240:
        return 1.22 if path else 0.31
    if path:
        return 0.30
    if before.endswith(("'", '"')):
        return 0.49
    recent = before[-80:].lower()
    if any(w in recent for w in (
        'pass:', 'pytest', 'seconds', 'elapsed', 'warnings',
        'tests in', 'ran ', 'finished in',
