    elif token == 'github' and tail.endswith('//'):
        value = 1.0
    elif token.strip().lower() == 'compatibility':
        value = 0.95
    elif token.strip().lower() in ('developer', 'developers'):
        value = 0.53
    elif token.strip().lower() in ('version', 'release', 'upgrade', 'update'):
