    elif token == ' PASS':
        value = -0.25
    return (doc, (tail + token)[-300:]), value

"""An approximate detector for the transition from code metadata to a declaration.

Documentation-comment endings, annotations/decorators, and the indentation and
keywords following them get positive values. Tests emphasize `void`, properties
emphasize `def`. Other text is mostly zero. The answer separator after </think>
has a small positive value; a comment bullet after a timestamp also fires.
Escaped code and line-numbered listings are supported. Scattered negative
name-specific activations are deliberately not modeled.
"""
import re

READS = ()
MODIFIERS = set('public private protected internal static final abstract virtual '
                'override async export default sealed readonly extern unsafe '
                'partial open pub weak'.split())
WORDS = MODIFIERS | set('def fn func function class interface struct enum mod '
                       'void String string boolean bool int long float double '
                       'char byte short var'.split())


def clean(line):
    line = re.sub(r'^\s*\d+(?:\t|:)\s*', '', line)
    return line.strip().strip('+-\\').strip()


def marker(line):
    line = clean(line)
    if line.endswith('*/'):
        return 'doc'
    if line.startswith('///') and line.endswith('>'):
        return 'doc'
    if re.match(r'@\w*property\b', line):
        return 'property'
    if line.startswith('@staticmethod'):
        return 'static'
    if line.startswith('@Override'):
        return 'override'
    if re.match(r'@(Test|Before|After)', line):
        return 'test'
    if re.match(r'@[A-Za-z_]', line):
        return 'annotation'
    if line.startswith('#[test]'):
        return 'rust_test'
    if line.startswith('#[') or re.match(r'\[[A-Z]\w*(?:\(|\])', line):
        return 'attribute'
    return 'none'


def predict(tail, token, escaped=False):
    if token.strip() == '•' and re.search(r'\d{1,2}:\d{2}\s*$', tail):
        return 3.5
    if token == '\n\n' and tail.endswith('</think>'):
        return 0.15
    word = token.strip()
    if word and word not in WORDS and '\n' not in token and '*/' not in token:
        return 0.0
    lines = tail.split('\n')
    current = clean(lines[-1])
    previous = lines[-2] if len(lines) > 1 else ''
    kind = marker(previous)
    # Recover multiline decorators whose final line is just a closing delimiter.
    if kind == 'none' and clean(previous) in (')', '})', ')]'):
        for line in reversed(lines[-9:-2]):
            if marker(line) != 'none':
                previous, kind = line, marker(line)
                break
    inline = re.match(r'^(@\w+(?:\([^)]*\))?|\[[A-Z]\w*\])\s*(.*)$', current)
    if inline:
        kind, current = marker(inline[1]), inline[2].strip()
    leading = all(w in MODIFIERS for w in current.split())
    leading |= current.isdigit() and token.startswith('\t')
    annotated = kind not in ('none', 'doc')
    if '*/' in token:
        block = tail[tail.rfind('/*'):] if '/*' in tail else tail
        tagged = bool(re.search(r'(?:^|[\s*])@\w', block))
        value = 4.6 if tagged else 2.0
        if current and not current.endswith('*'):
            value *= 0.25
        return value if '\n' in token else value * 0.5
    if '\n' in token:
        ending = token.split('\n')[0].strip()
        if ending and ending[-1] not in ')]>':
            return 0.0
        end = marker(lines[-1] + token.split('\n')[0])
        if end not in ('none', 'doc'):
            return (0.7 if escaped else 1.8)
        return 0.0
    if not word and leading:
        value = {'doc': 1.8, 'test': 4.8, 'override': 3.3,
                 'annotation': 2.6, 'attribute': 2.2,
                 'property': 2.5, 'static': 3.0, 'rust_test': 3.0}.get(kind, 0)
        if re.match(r'^\s*\d+\t', previous):
            value *= 0.4
        elif '\t' in token or len(token) == 1:
            value *= 0.5
        if lines[-1] and not current.isdigit():
            value *= 0.3
        return value
    if not leading or word not in WORDS:
        return 0.0
    if word == 'def':
        if not annotated:
            return 0.0
        return 14.0 if kind == 'property' else 4.0 if kind == 'static' else 10.5
    if word == 'fn':
        return (3.5 if escaped else 9.0) if kind == 'rust_test' else 0.7
    if word in ('public', 'private', 'protected', 'internal', 'pub'):
        if annotated:
            return 7.0 if word == 'private' and kind == 'annotation' else 3.8
        return 1.7 if kind == 'doc' else 0.0
    if word == 'void':
        return 6.7 if kind in ('test', 'attribute') else 0.6 if annotated else 0.0
    if word == 'weak' and annotated:
        return 6.5
    if word == 'func':
        return 7.0 if annotated else 0.5
    return 1.5 if annotated or kind == 'doc' else 0.0


def normalize(tail, token):
    escapes = {'n': '\n', 't': '\t', 'r': '\r'}
    if tail.endswith('\\') and token[:1] in escapes:
        tail = tail.rstrip('\\')
        token = escapes[token[0]] + token[1:]
    return tail, re.sub(r'\\+[ntr]', lambda m: escapes[m[0][-1]], token)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail, escaped = carry[1:] if carry and carry[0] == doc else ('', False)
    raw = prefix.token_strings[-1]
    tail, token = normalize(tail, raw)
    if '\n' in token:
        escaped = '\n' not in raw
    value = predict(tail, token, escaped)
    return (doc, (tail + token)[-1000:], escaped), float(value)

