    old_m_count = word.lower().count('m') if continues else 0
    m_word = continues and word.lower().startswith('m')
    previous_m = 'm' in previous.lower()

    value = 0.001
    if position == 0:
        value += 0.32
        if initial_m:
            value -= 1.16
        if token.strip().isdigit():
            value -= 0.23
    if initial_m:
        value -= 0.02
        if any(recent_m):
            value -= 0.03
        if previous_m:
            value -= 0.10
            if previous.lstrip().lower().startswith('m'):
                value -= 0.48
            if m_word:
                value -= 1.02
    if m_word:
        if m_count:
            value -= 0.40
        if old_m_count >= 2:
            value -= 0.44
        if previous.lower().endswith('m'):
