        elif simple.startswith(('过了', '过的')):
            value = -4.1
        elif simple.startswith(('过多', '过于', '过滤')):
            value = -2.3
        elif simple.startswith(('过去', '过来', '过后', '过得')):
            value = -1.2
        else:
            value = -0.4
    elif text in (' qua', ' quá'):
        value = -4.4
    elif word == '과':
        value = -0.9
    elif text.startswith(' ') and re.fullmatch(r'pass(?:ed|es|ing)?', word):
