"""Recognize common numerical prefixes and leading-zero strings.

19 and 20 are stronger in year-like contexts; 11, 21, and 31 also
respond. Leading zeros in identifiers and small decimals are different
from zeros inside ordinary integers or comma-grouped thousands.
Other tokens receive zero. A boundary correction handles an initial zero.
The constants approximate training averages, not exact arithmetic.
"""
import re

READS = ()
YEAR_CUES = {
    'in', 'since', 'from', 'born', 'died', 'during', 'between',
    'until', 'by', 'of', 'on', 'copyright', 'year', 'years',
}


def predict_digit(text, digit, position):
    run = re.search(r'[0-9]*$', text).group()
    before = text[:-len(run)] if run else text
    sep = before[-1:]
    previous = run[-1:]
    prior = re.search(r'([0-9]+)[.,:]$', before)
    words = re.findall(r'[A-Za-z]+', before[-70:])
    year_cue = bool(words and words[-1].lower() in YEAR_CUES)

    # The 19 prefix is particularly common in dates.
    if digit == '9':
        if run != '1':
            return 0.0 if previous == '1' else -0.06
        if year_cue:
            return 2.2
        if sep == '-':
            return 0.57
        if prior:
            return 0.4
        if sep == '(':
            return 1.95
        return 1.6 if sep == ' ' else 1.1

    # The response to a following 1 is strongest after small leading digits.
    if digit == '1':
        if previous in ('1', '2', '3'):
            if len(run) == 1:
                if previous == '3':
                    return 0.83
                return 0.77 if prior else 1.22
            if run[0] == '1':
                return 0.3
            return 0.77 if run[0] == '2' else 0.42
        if previous and previous != '0':
            return (0.17 if prior else 0.4) if len(run) == 1 else 0.13
        if not run and sep == '\n':
            return 0.2
        if not run and prior and len(prior[1]) == 1 and prior[1] != '0':
            return -0.08 if sep == ':' else 0.21
        return -0.18 if run.startswith('0') and sep != '.' else 0.0

    # Zeros: distinguish leading zeros, decimal fractions and integer interiors.
    zeros = len(run) - len(run.rstrip('0'))
    if run.startswith('0'):
        if not zeros:
            return -0.23
        if prior and prior[1][0] != '0':
            return 0.0 if sep == ',' else 0.65
        if sep == '[':
            return 2.9
        if zeros >= 3:
            return 2.8
        if len(run) == 1:
            return 2.5 if sep.isalpha() else 2.0
        return 1.3
    if len(run) >= 2:
        return 1.2 if zeros >= 3 else -0.08
    if run == '2':
        if year_cue:
            return 1.65
        if prior:
            return 0.17
        return 0.45 if sep == '-' else 1.1
    if run == '3':
        return 0.33
    if run:
        return -0.13
    if position == 0:
        return -0.8
    if sep.isalpha():
        return 1.65 if sep.isupper() else 1.14
    if sep == '.':
        return 1.04 if prior and prior[1][0] == '0' else 0.17
    if sep == '-':
        return 0.4
    return -0.12 if sep == '(' else 0.04


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text, position = ('', 0) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    value = 0.0
    if token in ('0', '1', '9'):
        value = predict_digit(text, token, position)
    return (doc, (text + token)[-120:], position + 1), value

