"""Digits that look like the middle of a year, or like zeros in a decimal fraction.

1. Year openers: the second digit of a number that starts 19, 20, 21, 11 or 31
   (as in "in 1|9|47", "2|0|21"); strongest when the number stands alone after a
   space or an open bracket, as in running prose.
2. Zeros in a decimal fraction: "0.0", "0.00", "0.000000". The first zero after the
   point is weak; a zero after one or more zeros that follow the point is strong.
Everything else predicts 0."""
READS = ()
DIGITS = "0123456789"
YEAR_OPENERS = {"19": 1.4, "20": 0.9, "21": 1.0, "11": 1.0, "31": 0.6, "00": 0.7}
PROSE_BEFORE = {" ", " ("}
CODE_BEFORE = {".", ",", "-", " -"}

def step(carry, prefix, upstream):
    toks = prefix.token_strings
    if len(toks) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    cur, prev = toks[-1], toks[-2]
    if cur == "0" and prev == ".":
        return None, 0.55
    if cur == "0" and prev == "0":
        j = len(toks) - 1
        while j >= 0 and toks[j] == "0":
            j -= 1
        if j >= 0 and toks[j] == ".":
            return None, 2.0
    if prev in DIGITS and cur in DIGITS:
        value = YEAR_OPENERS.get(prev + cur, 0.0)
        before = toks[-3] if len(toks) >= 3 else ""
        if before in PROSE_BEFORE:
            value *= 1.4
        elif before in CODE_BEFORE:
            value *= 0.5
        return None, value
    return None, 0.0

