"""A short-token r-a detector.

Look for 'ra' near a token's beginning, or for r and a straddling a
boundary between pieces of a word.  Short continuations, especially d
and t, get the largest response.  It also responds in the next piece
after 'ra'.  Spellings are transliterated so the same rules
also cover, for example, Cyrillic and Japanese.  These are approximate
shape averages, not a vocabulary lookup.
"""
import codecs
from functools import lru_cache
from anyascii import anyascii

READS = ()

@lru_cache(maxsize=32768)
def spelling(text):
    return anyascii(text).lower()


def response(text, previous, before_previous):
    s = spelling(text)
    p = spelling(previous)
    q = spelling(before_previous)
    word = s.lstrip()
    at = word.find('ra')
    cross = p.endswith('r') and s.startswith('a')
    inside = 0 <= at <= 2
    following = (p.endswith('ra') or
                 (p == 'a' and q.endswith('r')))
    following = following and bool(text and text[0].isalpha())
    other_vowel = p.endswith('r') and s[:1] in ('e', 'i', 'o', 'u')
    if not (cross or inside or following or other_vowel):
        return 0.0
    tail = s if cross else word[at + 1:] if inside else 'a' + s
    consonant = tail[1:2]
    n = len(word)
    if cross:
        if len(tail) <= 2:
            if consonant == 'd':
                return 3.68
            if consonant == 't':
                return 2.56
            return 0.35 if consonant in ('m', 'n') else 1.03
        if consonant == 't':
            if len(p.strip()) <= 3:
                return 2.05 if len(tail) <= 4 else 0.83
            return 0.58
        if consonant == 'd':
            return 1.57 if len(p.strip()) <= 4 else 0.34
        return 0.44 if len(tail) <= 3 else 0.20
    if other_vowel:
        return -0.03
    if n > 4:
        return 0.066
    if consonant == 'd':
        if n <= 3:
            return 2.44 if len(tail) <= 2 else 0.71
        return 1.01
    if consonant == 't':
        # A final written vowel (rate) is weaker than a consonant (rats).
        return 0.69 if tail[-1:] in ('a', 'e', 'i', 'o', 'u') else 1.50
    return 0.455 if n <= 3 else 0.173


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous = before_previous = ''
        pending = b''
    else:
        _, previous, before_previous, pending = carry
    raw = pending + prefix.token_bytes[-1]
    text, consumed = codecs.utf_8_decode(raw, 'replace', False)
    value = response(text, previous, before_previous)
