def closing(c):
    return ud.category(c) in ('Pe', 'Pf')


def value(text, previous, tail, marks):
    s = text.strip()
    p = previous.strip()
    end = previous[-1:]
    attached = bool(end and not end.isspace())
    word = re.search(r'[^\W\d_]+$', p)
    word = word[0] if word else ''
    whole_word = previous[:1].isspace()
    if '\x00' in text:
        return 1.87 if end.isalpha() else 0.4 if end.isspace() else 0.9
    if not s:
        return 0.0
    if s == 'right' and previous.endswith('\\'):
        return 0.57
    if s == 'import' and re.search(r'\bfrom\s+\S+\s*$', tail.split('\n')[-1]):
        return 0.8
    if s.startswith('<') and s[1:].isalpha():
        return 0.75
    if any(c.isalnum() for c in s):
        return -0.005
    if any(c in ',.;:' for c in s):
        return 0.0
    if '\n' in text:
        if s.endswith('>') and not tail.rsplit('<', 1)[-1].startswith('/'):
            return 0.8 if not text[0].isspace() and '<' in tail else 0.03
        return 0.03
    if s == '<':
        if text[0].isspace():
            return 0.08
        return 1.0 if len(word) > 1 and not word.islower() else 0.05
    if s == '>':
        if text[0].isspace() or not attached:
            return 0.0
        return 1.4 if p.startswith('<') else 1.2 if p.istitle() else 0.85
    if s == '’':
        return 0.8 if marks.get("'", False) and attached else 0.0
    if s in ('"', "'", '`', '$', '$$', '*', '**', '_', '__'):
        if text[0].isspace() or not attached:
            return 0.0
        if s in ('*', '**', '_', '__'):
            return (0.8 if s in ('*', '_') else 1.0) if marks.get(s, False) else -0.02
        if s == "'" and not marks.get(s, False):
            return -0.02
        if s in ('$', '$$') and not marks.get(s, False):
            return 0.05
        if s == '"' and re.search(r'(?<!\w)[frbuFRBU]{1,2}$', p):
            return 0.03
        if s == '`':
