    if s.endswith('>') and set(s) <= {'\\', '"', "'", '>'}:
        return 0.65 if attached and not text[0].isspace() else 0.03
    closes = [c for c in s if closing(c)]
    if closes:
        if not attached:
            return 0.03
        if s.endswith('$'):
            return 0.85
        if s.endswith('>'):
            return 0.8
        if s.endswith('('):
            return 0.8 if s.startswith(']') else 0.13
        if s.endswith(('\\', '/', '-', '{')):
            return 0.18
        if s.endswith('^'):
            return 0.47
        if not (closing(s[-1]) or s[-1] in '\"\'`$'):
            return 0.05
        if len(s) > 1:
            return (0.1 if text[0].isspace() else 0.33) if '(' in s else 0.5
        if s in (')', '）'):
            if end.isdigit():
                return 0.67
            if previous.lstrip().startswith('('):
                return 1.15
            return 0.57 if whole_word else 0.85
        if s == ']':
            return 0.57 if end.isdigit() else 0.8
        if s == '}':
            if text[0].isspace():
                return 0.15
            return 0.65 if end.isdigit() else 0.55
        return 0.65
