        return -0.9
    return -0.005


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail, marks = '', '', {}
    else:
        _, previous, tail, marks = carry
    text = prefix.token_strings[-1]
    prediction = value(text, previous, tail, marks)
    # The start-of-document suppression is strongest on short fragments.
    if not previous:
        word = text.strip()
        if word.isalpha():
            if not word.isascii():
                prediction = -0.45
            elif len(word) <= 2:
                prediction = -0.45 if len(word) == 1 else -0.3
            else:
                prediction = -0.13 if zipf_frequency(word, 'en') >= 4 else -0.25
        elif word.isdigit():
            prediction = -0.22
        else:
            prediction = -0.35 if text[:1].isspace() else -0.15
    for m in MARKS.finditer(text):
        if m[0] == '‘':
            marks["'"] = True
            continue
        mark = m[0]
        mark = {"‘": "'", "’": "'"}.get(mark, mark)
        before = text[m.start()-1:m.start()] if m.start() else tail[-1:]
        after = text[m.end():m.end()+1]
