        if mark in ("'", '_', '__') and before.isalnum() and after.isalnum():
            continue
        if marks.get(mark, False):
            marks[mark] = False
        elif not before or before.isspace():
            marks[mark] = True
        elif mark not in ('*', '**', '_', '__') and (
            not before.isalnum() or re.search(r'(?<!\w)[frbuFRBU]{1,2}$', tail)
        ):
            marks[mark] = True
    tail = (tail + text)[-160:]
    return (doc, text, tail, marks), float(prediction)

"""Predict the opening marks of list items, including markup lists.

Dashes and short numbered enumerators receive positive pulses, strongest
for '1.' and after a colon, heading, or blank line. Smaller pulses anticipate a
line-initial digit. Also recognize HTML list/table tags, LaTeX \\item,
and parameter-documentation labels. A document-initial "Title:" label
has a separate negative response; other in-line punctuation is zero.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, previous, blank, seen, comment = '', '', False, False, False
    else:
        _, line, previous, blank, seen, comment = carry
    token = prefix.token_strings[-1]
    left = line.strip(' \t\r>')
    left = re.sub(r'^(?://+|\*)\s*', '', left)
    mark = token.strip()
    # Ignore Markdown emphasis around an introductory colon.
    colon = previous.rstrip(' \t\r*_`').endswith((':', '：'))
    heading = bool(re.match(r'\s*#{1,6}\s', previous)
                   or re.fullmatch(r'\s*\*\*.+\*\*\s*', previous))
    previous_item = bool(re.match(r'\s*>?\s*(?:[-*•·]|\d+[.)])\s', previous))
    indent = bool(line[:1].isspace() or token.startswith(' '))
    value = 0.0
    if seen:
        if not left:
            if mark == '-':
                value = (1.8 + 2.0 * colon + 0.7 * blank
                         + 1.3 * indent + 1.2 * heading)
            elif mark == '*' and not comment:
                value = (1.6 + 0.8 * colon + 0.6 * blank
                         - 0.7 * indent + 0.8 * heading)
            elif mark in ('•', '·'):
                value = 0.45 + 0.3 * colon + 0.25 * blank - 0.25 * previous_item
            elif mark == '|':
                value = 0.2
            elif token == '1':
                value = (0.3 + 1.3 * colon + 0.5 * blank
                         - 0.15 * indent + 0.8 * heading)
            elif len(token) == 1 and token in '023456789':
                value = 0.04 + 0.17 * blank + 0.35 * previous_item - 0.07 * indent
        elif token == '.':
            if left.isdecimal():
                if left == '1':
                    value = 3.6 + 0.8 * colon + 0.7 * blank + 0.8 * heading
                elif len(left) == 1:
                    value = 2.0 + 0.2 * blank + 0.2 * previous_item + 0.8 * heading
                elif len(left) == 2:
                    value = 0.75 + 0.25 * previous_item
            elif len(left) == 1 and left.isalpha():
                value = 0.3 + 0.4 * colon + 0.8 * (left.islower() and indent)
    # Structural labels in explicit list and documentation syntax.
    name = token.lower()
    if line.endswith(('<', '</')):
        closing = line.endswith('</')
        line_start = bool(re.fullmatch(r'\s*(?://\s*)?</?', line))
        if name == 'li':
            value = (1.2 + 0.7 * line_start) if closing else (2.9 + 2.0 * line_start)
        elif name in ('td', 'tr'):
            value = 0.6 if closing else 0.9
            if name == 'tr' and closing:
                value += 0.7 * line_start
            elif not closing:
                value += 1.1 * line_start
        elif name in ('ul', 'ol'):
            value = (0.2 + 0.6 * line_start) if closing else (0.4 + 1.3 * line_start)
        elif name == 'summary':
            value = 0.5 if closing else 1.2
    if token == 'item' and line.endswith('\\'):
        value = 5.0 if left == '\\' else 3.5
    if token == 'param' and re.fullmatch(r'\s*(?:\*\s*)?[@:]', line):
        value = 2.9 if line.endswith(':') else 1.8
    elif token == ':param' and not left:
        value = 2.5
    if not seen and line == 'Title' and token == ':':
        value = -8.1
    text = line + token
    if '/**' in text:
        comment = True
    if '*/' in text:
        comment = False
    text = text.replace('\\n', '\n')
    if '\n' in text:
        lines = text.split('\n')
        for complete in lines[:-1]:
            if complete.strip(' \t\r>'):
                previous, blank = complete, False
            else:
                blank = True
        line, seen = lines[-1], True
    else:
        line = text
    return (doc, line, previous, blank, seen, comment), value

