"""layers.1.mlp.down_proj:226 -- a "list-item start" detector.

What it does: the component fires on the marker that opens a new line-item in a
list or table, in the way a reader would see it:
  * a "-" bullet at the start of a line (indentation and ">" quote marks allowed)
    -> about 2.2;
  * a line-initial number or letter followed by "." (e.g. "1.", "a.")
    -> about 2.2 for later items, 3.5 for a first item "1.", and 4.9 for a
    first item that follows a line ending in ":" (a list that is introduced);
  * the "1" that opens a list after a colon line -> 2.4, a "1" opening any other
    line -> 0.3, other digits that open a line -> 0.6 only if the previous line
    was already a list item, else 0;
  * a "•" bullet at line start -> 0.4;
  * an HTML table row or cell opening tag ("<tr", "<td") at line start -> 2.2.
Everything else predicts 0. Line state (start of line, whether the previous
non-blank line ends in ":" or started a list item) is carried from token to token
and reset at each document boundary.

Why: the component's large activations are list and table structure markers, and
it is near zero in running text (e.g. "Fig. 6", "3.5"). The constants are the
rough class means measured on training rows; within a class the activation
varies by about +-1.
"""
import re

READS = ()
PREFIX = ("", ">", "#", "<", "</")  # tokens that may sit before a marker on its line


def _fresh():
    return {"bol": True, "colon": False, "cur": "", "lead": False,
            "first": False, "tag": False, "item": False}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    tok = toks[-1]
    if carry is None or len(toks) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        carry = _fresh()
    s = carry
    bare = tok.strip()
    value = 0.0
    # 1. the "." after a line-initial enumerator (number or letter)
    if s["lead"] and tok == ".":
        value = 4.9 if s["first"] and s["colon"] else (3.5 if s["first"] else 2.2)
    # 2. bullets at the start of a line
    elif s["bol"] and bare == "-":
        value = 2.2
    elif s["bol"] and bare == "•":
        value = 0.4
    # 3. a number at the start of a line
    elif s["bol"] and bare == "1":
        value = 2.4 if s["colon"] else 0.3
    elif s["bol"] and bare.isdigit() and s["item"]:
        value = 0.6
    # 4. HTML table row / cell opening tags
    elif s["tag"] and bare in ("tr", "td"):
        value = 2.2

    # update the line state with this token
    literal_nl = tok == "n" and len(toks) > 1 and toks[-2].endswith("\\")  # "\n" escape in code
    if literal_nl:
        s["cur"] = s["cur"][:-1]
        parts = ["", ""]
    else:
        parts = tok.split("\n")
    s["lead"] = s["bol"] and (bare.isdigit() or (len(bare) == 1 and bare.isalpha()))
    s["first"] = bare == "1"
    s["tag"] = s["bol"] and bare in ("<", "</")
    if len(parts) > 1:
        line = (s["cur"] + parts[0]).strip()
        if line:
            s["colon"] = line.endswith(":")
            s["item"] = bool(re.match(r"^(\d+\.|[-•])\s", line + " "))
        s["cur"] = parts[-1]
        s["bol"] = True
    else:
        s["cur"] += tok
        if bare not in PREFIX:
            s["bol"] = False
    return s, float(value)

