"""A decimal/version-point detector with a few structured-text responses.

A first dot after a short integer is positive, especially after zero,
a currency sign, or a path/version marker.  Longer integers give weaker
responses.  List numbers and already dotted numbers are discounted.
HTTP/WWW URL markers and the uppercase OBSERVATION heading also respond.
The constants summarize training examples; other lexical variation is omitted.
"""
import re

READS = ()


def number_point(text):
    match = re.search(r'([0-9]+)$', text)
    if not match:
        return -0.02
    digits = match.group()
    before = text[:match.start()]
    last = before[-1:]
    size = len(digits)
    if re.search(r'\d\.$', before):
        return -0.17 if size >= 4 else 0.0
    if re.search(r'(?:^|\n|\\n)[ \t>#*]*$', before):
        return 0.35 if digits == '0' else (-0.05 if size == 1 else 0.04)
    if re.search(r'\.\s*$', before):
        return 0.0
    if last in {'$', '£', '€', '¥'}:
        return 1.22 if digits == '0' else max(0.15, 1.22 - 0.24 * size)
    version = (re.search(r'[_vV]$', before)
               or (last == '/' and not re.search(r'\d/$', before))
               or ('/' in before and re.search(r'[a-zA-Z]-$', before)))
    if version:
        return 1.05 if digits == '0' else max(0.15, 1.07 - 0.22 * size)
    if re.search(r'[a-zA-Z]$', before):
        return 0.34 if digits == '0' else 0.22
    value = 0.75 if digits == '0' else (0.66 - 0.11 * size)
    if size >= 4:
        value = 0.10
    if last in {'=', '^'}:
        value *= 0.7
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    text = '' if carry is None or carry[0] != document else carry[1]
    token = prefix.token_strings[-1]
    value = 0.0
    if token == '.':
        value = number_point(text)
    elif token == '://':
        value = 1.0 if text.endswith('http') else 0.16
    elif token.strip() == 'www':
        value = 1.15 if token == 'www' else 0.52
    text = (text + token)[-160:]
    line = text.rsplit('\n', 1)[-1].strip()
    if token.strip() and len(line) >= 3 and 'OBSERVATION'.startswith(line):
        value = 0.40 if line == 'OBSERVATION' else 0.65
    return (document, text), value

programs.haiku:
"""Decimal points inside running text, plus the 'www' and '://' of web addresses.

A decimal point is the '.' right after a whole-number part of 1-3 digits when that number
sits inside a line of text: '0.5', '1.25', 'v1.2', '$1.50'. Silent when the number starts a
line or follows a sentence end, a '#' heading or a '-' bullet. Strongest for a single
leading 0 or 1, and somewhat stronger when the number follows '(', '$', 'v', '=', '@'.
'www' and '://' (in 'http://www.') respond too, weakly.
"""
READS = ()

DIGITS = set("0123456789")
NOT_INLINE = {".", "#", "-", ":", "\n"}
STRONG_BEFORE = {" v", " $", " (", "(", "=", "@", "{", "__", "≈"}


def _is_digits(s):
    return len(s) > 0 and all(ch in DIGITS for ch in s)


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    t = prefix.position
    cur = toks[t].strip()
    if cur == "www":
        return carry, 1.1
    if cur == "://":
        return carry, 0.45
    if toks[t] != "." or t == 0:
        return carry, 0.0
    k = 0
    while t - 1 - k >= 0 and _is_digits(toks[t - 1 - k]):
        k += 1
    if k == 0 or k > 3:
        return carry, 0.0
    before = toks[t - k - 1] if t - k - 1 >= 0 else "\n"
    if "\n" in before or before.strip() in NOT_INLINE:
        return carry, 0.0
    if k == 1:
        value = {"0": 0.7, "1": 0.55}.get(toks[t - 1], 0.3)
    else:
        value = 0.3
    if before in STRONG_BEFORE:
        value *= 1.2
    return carry, value

