"""Cloth/布 spellings, with weaker responses to their subword fragments.

This is a lexical rather than a general textile-topic detector. It gives
large negative values to cloth and 布, smaller ones to fabric and verbs
containing 布. Split spellings are recognized across the previous token,
including unfinished UTF-8 bytes. Similar fragments (bro-, -loth, -roth)
also respond; ordinary clothing words usually do not. Initial escaped
newlines and quotes have a separate negative response.
"""
import cedict

READS = ()

# Chinese verbs containing the cloth character: publish, announce, distribute,
# promulgate, spread throughout, and arrange.
VERBS = {
    '发布': -2.6, '發布': -2.4, '公布': -3.6, '宣布': -1.1,
    '颁布': -1.5, '分布': -1.6, '遍布': -1.4, '布置': -1.7,
}


def response(s, previous):
    w, before = s.strip().lower(), previous.lower()
    if w == 'cloth':
        return -9.2 if s == ' cloth' else -7.8
    if w == 'broth':
        return -3.8
    if w in ('fabric', 'fabrics'):
        if previous.strip().lower() in ('de', 'du', 'le', 'que'):
            return -0.5
        if previous.strip().lower() in ('cotton', 'linen', 'felt'):
            return -4.7
        return -3.0 if s == ' fabric' else -1.9
    if s in ('布', '佈'):
        # Capitalized dictionary glosses suggest a completed proper name.
        if len(previous) >= 2:
            glosses = cedict.glosses(previous[-2:] + s)
            if any(g[:1].isupper() for g in glosses):
                return -0.7
        if previous.strip() in ('发', '發', '公', '宣', '配', '画', '畫'):
            return -3.5
        if previous.endswith(('乔', '喬', '阿')):
            return -4.0
        if previous.endswith(tuple('棉红紅擦烂爛剪纱紗')):
            return -11.5
        return -8.0 if s == '布' else -6.0
    root = s.rstrip('了的在')
    if root in VERBS:
        factor = 1.0
        if s.endswith(('了', '在')):
            factor = 0.7
        elif s.endswith('的'):
            factor = 0.4
        return VERBS[root] * factor
    if w == 'clo':
        if before.endswith('wash'):
            return -5.0
        return -1.7 if s == 'Clo' else -0.8
    if s in ('th', 'ths', 'the', 'thed', 'thes', 'thing', 'thy'):
        if before.endswith(('clo', 'slo')):
            if s in ('th', 'ths'):
                return -11.7
            if s == 'thing':
                return -1.4
            return -5.7 if s in ('the', 'thed') else -3.4
        if s == 'thes' and before.endswith('lo'):
            return -3.4
        if s in ('th', 'ths', 'thy'):
            if before.endswith(('lo', 'bro', 'gro', 'tro', 'fro')):
                return -6.0
            if before.endswith('ro'):
                return -2.0
            if before.endswith('o'):
                return -1.1
        if s == 'th':
            return 0.17 if before[-1:].isdigit() else -0.2
    if s == 'loth' and before.endswith('c'):
        return -12.0
    if s == 'rics' and before.endswith('fab'):
        return -4.0
    if s == 'ro' and before.endswith('b'):
        return -1.9
    if w == 'bro':
        return -3.8 if before.endswith('z') else -0.9
    if s == 'lo' and before.endswith('c'):
        return -2.4 if not before[-2:-1].isalpha() else -0.5
    if s == 'thro':
        return -1.2
    if s == 'ath' and before.endswith('clo'):
        return -4.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_document = carry is None or carry[0] != doc
    previous, tail = ('', b'') if new_document else carry[1:]
    s, raw = prefix.token_strings[-1], prefix.token_bytes[-1]
    value = response(s, previous)
    if new_document and s in ('\\n', '\\"'):
        value = -1.83  # escaped text at the start of a row/document
    if raw == b'\xb8' and tail.endswith((b'\xe5', b'\xeb')):
        value = -4.5  # incomplete Han/Hangul spelling sharing this byte
    elif raw == b'\x83' and tail.endswith(b'\xe5\xb8'):
        value = -9.5  # completes 布
    return (doc, s, (tail + raw)[-2:]), value

