    """carry: the last 16 characters of the document so far."""
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        carry = ""
    token = prefix.token_strings[-1]
    if token in CJK:
        return "", CJK[token]
    text = ((carry or "") + token)[-16:]
    start = len(text)
