        start -= 1
    word = text[start:].lower()
    whole = start == 0 or not (text[start - 1].isascii() and text[start - 1].isalpha())
    value = 0.0
    if word.endswith("cloth"):
        value = ENDINGS["cloth"]
    elif whole and word in WHOLE_WORDS:
        value = WHOLE_WORDS[word]
