    'previous preceding prior subsequent former earlier '
    'later '
    .split()
)
SCHOOL_STAGES = set(
    'freshman freshmen sophomore junior senior graduate undergraduate '
    'undergrad grad '
    .split()
)
JURISDICTIONS = set(
    'local federal state national international regional district '
    'county municipal provincial community '
    .split()
)
CIVIC_HEADS = set(
    'association society foundation institute institutes council '
    'committee assembly commission congress federation union '
    'conference convention register system market education '
    'development department bureau '
    .split()
)
