        if p == 'academic':
            return -0.8
        if p in RELATIVE:
            strong = w == 'years' and p not in {'earlier', 'later'}
            return 1.2 if strong else 0.5
        if p in {'fiscal', 'financial', 'tax', 'plan', 'accounting'}:
