programs.haiku:
"""Layer-1 MLP down_proj component 235.

What it does, in plain terms:

1. Tier nouns. It switches on at the head word of a phrase that names a rung or stage in an
   ordered system: "middle years", "senior year", "early years", "local level", "grade
   level", "undergrad level", "main stage", "first division", "premier league". The
   strongest cases follow a word that places the noun in a sequence or hierarchy (a school
   stage, an ordinal, a government or competition tier). "College Algebra" counts too.

2. Organisation nouns after a modifier ("National Assembly", "World Championship").

3. First token of a document. A row packs documents end to end and the model resets
   attention at each one, so the first token has no context and its value depends only on
   the token itself. Mid-sentence joiners (comma, "of", "to", "and", "or") push it positive;
   capitalised sentence openers and heading marks ("The", "#", "##") push it negative.

Everything else predicts 0. The component is almost always silent; these rules catch its
largest, most readable spikes and nothing of the diffuse small activity.
"""

READS = ()

TIER_NOUNS = {
    "year", "years", "level", "levels", "stage", "stages", "division", "sector",
    "league", "period", "phase", "tier", "algebra",
}

ORG_NOUNS = {
    "assembly", "council", "alliance", "championship", "cup", "league", "register",
    "secretary", "committee", "series", "conference", "union", "olympic", "foundation",
    "society", "market",
}

MODIFIERS = {
    "middle", "primary", "early", "senior", "junior", "first", "second", "third",
    "local", "federal", "national", "international", "world", "premier", "grade",
    "grad", "graduate", "undergrad", "college", "main", "district", "higher",
    "private", "global", "individual", "secondary", "elementary", "regional",
}

JOINERS = {",", " of", " to", " and", " or", " in", " that", " with", " was", ")"}
OPENERS = {"The", "A", "An", "T", "P", "R", "#", "##", "-", "//"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    if len(prefix.document_ids) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        if raw in JOINERS:
            return carry, 0.4
        if raw in OPENERS:
            return carry, -0.5
        return carry, 0.0
    word = raw.strip().lower()
    before = prefix.token_strings[-2].strip().lower()
    modified = before in MODIFIERS
    if word in TIER_NOUNS:
        return carry, 1.2 if modified else 0.1
    if word in ORG_NOUNS and modified:
        return carry, 0.4
    return carry, 0.0

