from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'it', 'es', 'fr', 'pt', 'ro', 'hu', 'pl', 'id', 'de',
             'ca', 'cs', 'sk', 'tr', 'vi', 'sv', 'nl', 'fi')


@lru_cache(maxsize=20000)
def word_scores(word):
    return tuple(zipf_frequency(word, lang) for lang in LANGUAGES)


def language(text):
    words = re.findall(r'[^\W\d_]+', text.lower(), re.UNICODE)[-12:]
    words = [w for w in words if len(w) > 1]
    if not words:
        return 'en'
    scores = [sum(0.8 ** age * min(5.5, word_scores(w)[i])
                  for age, w in enumerate(reversed(words)))
              for i in range(len(LANGUAGES))]
    best = max(range(len(scores)), key=scores.__getitem__)
    # A strongly English last word can override a run of foreign names.
    last = word_scores(words[-1])
    if last[0] > last[best] + 1.2:
        return 'en'
    return LANGUAGES[best]


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    old = '' if first else carry[1]
    token = prefix.token_strings[-1]
    text = (old + token)[-350:]
    value = 0.0
    if token in (' à', ' À', "'à", 'à', ' á', ' Á'):
        if token == 'à' and old and old[-1].isalpha():
            return (doc, text), 0.0
        lang = language(old)
        value = {'pt': -0.23, 'vi': 0.0}.get(lang, -0.72)
        if token == ' À' and lang == 'fr' and not first:
            value = -1.05
        if token in (' á', ' Á'):
            value = -0.6 if lang in ('es', 'pt') else 0.0
    elif token in (' a', ' A', 'A', 'a', ' ad', ' Ad', ' di', ' po'):
        lang = language(old)
        if token == 'a' or (token == 'A' and old
                            and old[-1].isalpha()):
            return (doc, text), 0.0
        if token.strip().lower() == 'a':
            value = {'it': -0.76, 'es': -0.67, 'fr': -0.25,
                     'pt': -0.28, 'ro': -0.3, 'ca': -0.2}.get(lang, 0.01)
            if token in (' A', 'A'):
                value = {'it': -0.25, 'es': -0.55, 'fr': -0.55,
                         'pt': -0.2, 'ro': -0.2}.get(lang, 0.0)
                if (lang in ('fr', 'es')
                        and re.search(r'[.!?\n]\s*$', old)):
                    value = -0.9
        elif token.strip().lower() == 'ad' and lang == 'it':
            value = -0.9
        elif token == ' di' and lang == 'id':
            value = -0.6
        elif token == ' po' and lang in ('pl', 'cs', 'sk'):
            value = -0.5
        if token == ' a' and re.search(
                r'\b(?:sin|cos|tan|cot|sec|csc|log)\s*$', old):
            value = 0.0
        if first and token.strip().lower() == 'a':
            value = -0.32 if token == 'A' else -0.24
    # Russian: to, about, about-before-a-vowel, along/on.
    elif token.lower() in (' к', ' о', ' об', ' по'):
        value = {' к': -0.35, ' о': -0.43,
                 ' об': -0.29, ' по': -0.44}[token.lower()]
    # With/from, on, for/behind.
    elif token.lower() in (' с', ' на', ' за'):
        value = {' с': -0.15, ' на': -0.1, ' за': -0.2}[token.lower()]
    # At/by and from have a small positive response.
    elif token.lower() in (' у', ' от'):
        value = 0.16
    # German locative preposition.
    elif token in (' bei', ' Bei'):
        value = -0.3
    return (doc, text), value

"""Sparse responses to text-formatting and software-boilerplate boundaries.

Keep a short, document-local text tail. Recognize repeated punctuation,
LaTeX array arguments, a few standard code/documentation idioms, and chat
markup. Unrecognized text receives zero activation. This does not
attempt to predict isolated personal names or arbitrary identifier pairs.
"""
READS = ()

MARKUP = {
    '<think>': -0.54,
    '</tool_response>': -0.30,
    '<tool_call>': 0.16,
    '</tool_call>': 0.095,
    '<tool_response>': -0.08,
    '</think>': -0.035,
    '<|im_start|>': -0.04,
    '<|im_end|>': -0.03,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    text = (old + token)[-100:]
    value = MARKUP.get(token, 0.0)

    # Typographic leaders and table rules have token-size-specific responses.
    if token == '··':
        value = 0.72
    elif token in ('____', '________') and old.endswith('_'):
        n = len(old) - len(old.rstrip('_'))
        if n == 64:
            value = 3.0
        elif 32 <= n <= 34:
            value = 1.6
        elif 16 <= n <= 18:
            value = 0.5
        else:
            value = 0.2
    elif token == '}{' and old.endswith('array'):
        value = 1.7

    # Recognizable boilerplate, with the response at the indicated boundary.
    elif token == '/' and old.endswith('.git'):
        value = -0.85
    elif token == '-lang' and old.endswith('rust'):
        value = -2.3 if old.endswith('doc.rust') else -1.25
    elif token == ' License' and old.endswith('under the Apache'):
        value = 1.6
    elif token == ' WARRANTY' and old.endswith('WITHOUT'):
        value = 1.4
    elif token == ' HOLDERS' and old.endswith('COPYRIGHT'):
        value = -1.2
    elif token == '-user' and old.endswith('begin'):
        value = 0.5
    elif token in (' -', ' --') and old.endswith('#SBATCH'):
        value = -0.65
    elif token == ' TABLE' and old.endswith('LOCK'):
        value = -1.6
    elif token == '_CHARACTER' and old.endswith('@OLD'):
        value = -1.55
    elif token == '@example' and old.endswith('firstname.lastname'):
        value = 1.0
    elif token == '_EMAIL' and old.endswith('PRESIDIO_ANONYMIZED'):
        value = -1.65
    elif old.endswith('.springframework'):
        if token in ('.web', '.data', '.context'):
            value = 1.0
        elif token == '.boot':
            value = 0.75
    elif token == '/' and old.endswith('multipart'):
        value = -1.7

    return (doc, text), value

"""Approximate two responses: definite descriptions and de-like spellings.

Suitability words after "the" receive negative values. Choosing contexts
strengthen "right"; spatial contexts weaken it. A few weaker rules cover
ordinals, abilities, and kind/type-of phrases.

Internal de-/di-/dy- fragments receive positive values, with length and
common-completion discounts. Cyrillic is transliterated for this rule.
Separate spelling rules cover Japanese deka/dekka and denja fragments.
All state resets at document boundaries; unmatched tokens receive zero.
"""
import re
import math
from functools import lru_cache
from wordfreq import top_n_list, zipf_frequency
import unicodedata
from anyascii import anyascii

READS = ()

# Frequency of a familiar word that could complete a spelling fragment.
LANGUAGES = ('en', 'fr', 'es', 'pt', 'de', 'ro')
COMPLETION_FREQUENCY = {}
for language in LANGUAGES:
    for entry in top_n_list(language, 50000):
        if entry.startswith(('de', 'dé', 'di', 'dy')):
            frequency = zipf_frequency(entry, language)
            for length in range(1, len(entry) + 1):
                fragment = entry[:length]
                COMPLETION_FREQUENCY[fragment] = max(
                    frequency, COMPLETION_FREQUENCY.get(fragment, 0))


@lru_cache(maxsize=10000)
def familiarity(fragment):
    return COMPLETION_FREQUENCY.get(fragment, 0) or max(
        zipf_frequency(fragment, language) for language in LANGUAGES)


SUITABILITY = {'correct', 'appropriate', 'necessary', 'proper', 'ideal'}
OPTIMIZATION = {'best', 'optimal', 'required', 'desired', 'requisite', 'ultimate'}
OPPORTUNITY = {'chance', 'opportunity'}
CAPACITY = {'ability', 'capability', 'skills', 'need'}
POSSESSIVES = {'my', 'your', 'his', 'her', 'its', 'our', 'their'}
CHOOSING = {'choose', 'choosing', 'pick', 'picking', 'find', 'finding',
            'select', 'selecting', 'discovering'}
SPATIAL = {'on', 'to', 'from', 'towards', 'toward'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        word, previous, before, history = '', '', '', ()
    else:
        _, word, previous, before, history = carry
    token = prefix.token_strings[-1]
    current = token.strip().lower()
    prev = previous.strip().lower()
    earlier = before.strip().lower()
    value = 0.0

    if prev == 'the':
        if current == 'right':
            value = -3.3
            if earlier in SPATIAL:
                value = -0.9
            if earlier in {'of', 'through'}:
                value = -1.8
            if earlier in {'with', 'under', 'just', 'be', 'is'}:
                value = -5.4
            if earlier == 'in':
                value = -2.4
            if 'left' in history:
                value = -0.7
            if ((any(w in CHOOSING for w in history)
                 and earlier not in SPATIAL | {'of', 'through'})
                    or earlier == 'need'):
                value = -9.5
        elif current == 'perfect':
            value = -7.0
        elif current == 'wrong':
            value = -4.7
        elif current in SUITABILITY:
            value = -3.1
        elif current in OPTIMIZATION:
            value = -1.0
        elif current in OPPORTUNITY:
            value = -3.2 if current == 'chance' else -1.0
        elif current in CAPACITY:
            value = -1.2
        elif current in {'next', 'help', 'exact', 'complete'}:
            value = -0.65
        elif current in {'latest', 'present', 'first'}:
            value = -0.2
        elif current == 'time':
            value = -0.2
            if earlier in {'have', 'has', 'had', 'take', 'taking', 'find'}:
                value = -2.4
        if previous.strip() == 'The':
            value *= 0.5
    elif prev in POSSESSIVES:
        if current == 'next':
            value = -1.4
        elif current == 'first':
            value = -0.5
    elif prev == 'very' and current in {'best', 'first'}:
        value = -1.2

    if current == 'of' and prev in {'kind', 'type', 'sort', 'kinds', 'types', 'sorts'}:
        value = -0.15
        if earlier in {'the', 'that'}:
            value = -2.0 if prev == 'kind' else -1.0

    # This is a spelling condition, not a claim about the word's meaning.
    if word and token and token[0].isalpha():
        root = ''.join(c for c in unicodedata.normalize('NFD', word.lower())
                       if not unicodedata.combining(c))
        cyrillic = root.startswith('д')
        if cyrillic:
            root = anyascii(root).lower()
        if root.startswith(('de', 'di', 'dy')):
            strength = 0.6
            if root.startswith('de'):
                strength = 1.8
            if len(root) > 2 and root[2] in 'aeiouvw':
                strength = 0.6
            if root.startswith('dem'):
                strength = 4.3
            if root.startswith(('dis', 'dys')):
                strength = 2.4
            if root.startswith('des'):
                strength = 5.8
            if cyrillic and root == 'de':
                strength = 0.4
            elif cyrillic and root.startswith('dek'):
                strength = 3.2
            commonness = familiarity((word + token).lower())
            damping = max(0.05, 1 - 0.25 * max(0, commonness - 3))
            distance = 0.55 * max(0, len(root) - 3)
            distance += 0.16 * max(0, len(token) - 3)
            value = strength * damping * math.exp(-distance)

    # Colloquial Japanese "big": de-ka / de-k-ka, and the loan "danger".
    if token == 'カ' and (previous == 'デ'
                         or (previous == 'ッ' and before == 'デ')):
        value = 4.1
    elif token == 'ッ' and previous == 'デ':
        value = 0.55
    elif token == 'イ' and previous == 'カ':
        if before == 'デ':
            value = 1.8
        elif before == 'ッ' and len(history) >= 3 and history[-3] == 'デ':
            value = 0.7
    elif token.startswith('ジャ') and previous == 'デン':
        value = 1.8

    if token.isalpha():
        word = (word + token)[-40:]
    else:
        tail = re.search(r'[^\W\d_]+$', token)
        word = tail[0] if tail else ''
    history = (history + (current,))[-7:]
    return (doc, word, token, previous, history), value

"""Sparse spelling cues, chiefly the adapt-/adapter family.

The negative response follows this stem across token boundaries, including
Cyrillic transliterations. Inflection and token splitting change its size.
Smaller responses cover adopt forms, Japanese ata, and Chinese adaptation
words. Short fragments forming a dz cluster are positive. Everything else is
near zero; no general semantic understanding of adaptation is assumed.
"""
import regex as re
from functools import lru_cache
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=20000)
def roman(text):
    return anyascii(text).lower()


@lru_cache(maxsize=100000)
def response(before, token):
    # A new word (or a capitalized identifier part) does not extend the old one.
    join = bool(token and token[0].isalpha())
    if token[:1].isupper() and before[-1:].islower():
        join = False
    old = roman(before) if join else ''
    current = roman(token)
    text = old + current
    boundary = len(old)
    match = re.search(r'adapt[a-z]*', text)
    if match and match.end() > boundary:
        word = match.group()
        # Do not keep firing on later words or arbitrary identifier suffixes.
        if match.start() < boundary and not old.endswith(('ad', 'adap', 'adapt')):
            return -0.001
        if word.startswith('adaptogen'):
            return -0.001
        if word.startswith('adaptive'):
            return -2.1 if match.start() < boundary else -0.7
        if word.startswith('adaptable') or word.startswith('adaptability'):
            return -3.5
        if match.start() < boundary:
            # A small suffix can carry a large response after a split stem.
            if re.search(r'\p{Script=Cyrillic}', before + token):
                if old.endswith('adap'):
                    return -5.3 if current.startswith('tiv') else -14.0
                return -6.0
            if current.startswith(('er', 'or')):
                return -4.0
            return -6.0
        value = -7.2 if word == 'adapting' else -5.3
        if word == 'adapted':
            value = -4.8
        if word.startswith(('adapter', 'adaptor')):
            value = -6.0 if 'Adapter' in token else -4.5
        # A stem embedded inside a single larger identifier is less strong.
        if match.start() and text[match.start()-1].isalpha():
            value *= 0.4
        if token.startswith('.'):
            value *= 0.75
        return value
    if text.endswith('adap'):
        return -13.0 if old.endswith(('ad', 'd')) else -2.5
    # A split a-d-p spelling shares the strong negative response.
    if old.endswith('ad') and current == 'p':
        return -5.2
    match = re.search(r'adopt[a-z]*', text)
    if match and match.end() > boundary:
        if old.endswith('adopt'):
            return -0.4
        if match.start() < boundary:
            return -4.0
        return -0.8 if match.group().startswith(('adopted', 'adoption')) else -1.4
    # Romance adopt/adapt forms: adotar, adottare, adattare.
    if old.endswith('ad') and current.startswith(('ot', 'atta')):
        return -3.0
    if before.endswith(('あ', '当')) and token.startswith('た'):
        return -5.2
    if before.endswith(('适', '適')):
        if token.startswith('配'):
            return -6.8
        if token.startswith(('应', '應', '応')):
            return -4.0
    if token == '适应':
        return -0.45
    # The dz cluster is strongest in Cyrillic and after an a-d sequence.
    if old.endswith('d') and token[:1].lower() in 'zźžз' and token:
        if token[:1].lower() == 'з':
            if len(token) > 1 and token.lower() != 'зв':
                return -0.001
            return 7.0 if before in ('Д', 'д') else 4.5
        # Longer Polish suffixes such as -zenie are not this cue.
        if len(token) > 3 or (len(token) > 1 and not token.isascii()):
            return -0.001
        if current.startswith('ze'):
            return 8.0 if old.endswith('ad') else 3.0
        return 3.5 if old.endswith('ad') else 1.0
    return -0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(before, token)
    # Only the end of the current word is needed at the next position.
    word = re.search(r'[^\W\d_]+$', before + token)
    tail = word.group()[-24:] if word else ''
    return (doc, tail), value

programs.haiku:
"""Fixed-pair completion detector (layer 1, MLP down_proj, component 240).

This component is almost always silent. It goes strongly negative on the second
half of a fixed two-part phrase, the word that completes a pair the text has just
opened:

  * "and/or":      the "/or" in "... and/or ..."                       (about -6.6)
  * "he/she", "to/from", "I/O": the slash-joined second half           (about -6 to -14)
  * "his or [her]", "he or [she]": the pronoun after "or"               (about -8 to -15)
  * "one or [more]", "or [several]", "or [without]", "and [from]"       (about -4 to -6)
  * "his [or] her", "he [or] she", "one [or] more": the "or" itself      (about -3 to -5)

Everything else predicts 0. The prediction is negative (the component writes a
negative multiple of its output direction) and it uses only the current and the
previous token, so it is stateless.
"""

READS = ()

PAIR_FIRST_SLASH ={"and", "to", "from", "he", "I", "O", "E", "c"}
OR_PRONOUN = {" her", " she", " hers", " his", " him", " he"}
OR_QUANTIFIER = {" more", " several", " all", " every", " without", " from"}
OR_EITHER = {" his", " he", " one", " two", " some"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if len(prefix.token_strings) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    prev = prefix.token_strings[-2]
    value = 0.0
    if cur.startswith("/") and len(cur) > 1 and prev.strip() in PAIR_FIRST_SLASH:
        value = -6.0  # slash-joined second half: and/or, he/she, to/from, I/O
    elif prev == " or" and cur in OR_PRONOUN:
        value = -8.0  # his or [her], he or [she]
    elif prev in (" or", " and") and cur in OR_QUANTIFIER:
        value = -4.0  # one or [more], or [several], each and [every]
    elif cur == " or" and prev in OR_EITHER:
        value = -3.0  # his [or] her, one [or] more
    return carry, value

"""Layer-1 MLP output feature 241 (layers.1.mlp.down_proj:241).

What it does, in plain terms: a negative signal on punctuation that closes a
short clause or short line, and a strong negative on the first line break
after a chat-role or tool tag. The signal fades as the clause gets longer.
It is positive on the first token of each document. Ordinary words, digits
and spaces are near zero.

Rules, first match wins. They use the current token, the one before it (same
document only), and the clause length: how many tokens since the last sentence
end or line break. The count is kept in the carry and reset at each document.
  1. First token of a document:                                  +0.5
  2. Line break right after "user", "assistant", "<tool_call>"
     or "<tool_response>":                                       -0.8
  3. Punctuation after a word, scaled by clause length:
       colon ":"                    -0.4, no length factor (-0.15 after a non-word)
       "!" "?"                      -0.85
       "." ";" "—" or a line break  -0.4
       "," ")" "]"                  -0.15
     Clause length factor: up to 4 tokens x1, up to 8 x0.8,
     up to 12 x0.35, longer x0.1. Short clauses are the strongest.
  4. Anything else:                                               0
"""

READS = ()

ROLE_TAGS = {"user", "assistant", "<tool_call>", "<tool_response>"}
COLONS = {":", "：", " :"}
ENDS = {".", "!", "?", "。", "！", "？"}
LOUD = {"!", "?", "！", "？"}
DASHES = {";", "—", " —"}
CLOSERS = {",", "，", ")", "]", ");"}


def is_break(token):
    return "\n" in token or token in ENDS or token in DASHES


def clause_factor(n):
    if n <= 4:
        return 1.0
    if n <= 8:
        return 0.8
    if n <= 12:
        return 0.35
    return 0.1


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    cur = tokens[-1]
    first = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    n = 1 if first else carry + 1
    next_carry = 0 if is_break(cur) else n
    if first:
        return next_carry, 0.5
    prev = tokens[-2]
    after_word = prev.rstrip()[-1:].isalpha()
    if "\n" in cur and prev.strip() in ROLE_TAGS:
        return next_carry, -0.8
    if cur in COLONS:
        return next_carry, -0.4 if after_word else -0.15
    if cur in LOUD and after_word:
        base = -0.85
    elif (cur in ENDS or cur in DASHES or "\n" in cur) and after_word:
        base = -0.4
    elif cur in CLOSERS:
        base = -0.15
    else:
        return next_carry, 0.0
    return next_carry, base * clause_factor(n)

"""Component layers.1.mlp.down_proj:242 (v3): negative on words naming a type, a setting or a measured quantity.

The component reads only the current token. Its activation is negative on
  * any 'type' word (type, Type, _type, types, subtype, 类型, тип, ...): about -0.6;
  * software settings and parameters (size, value, command, argument(s), option(s),
    version, parameter(s), config, setting(s), attribute(s), property, flag(s)): about -0.35;
  * measured properties and dimensions (length, width, height, depth, weight,
    temperature, pressure, frequency, speed, rate, distance, voltage, ...): about -0.18;
  * other technical nouns (result, method, format, status, mode, source, context, output,
    input, data, error, action, kind, module, ...): about -0.2.
It is near zero on other tokens and on the first token of each document, which are
left at 0. Outside these words the activation is diffuse and is not modelled.
"""

READS = ()

TYPE_STEMS = ("type", "тип", "类型", "型", "tipo")
SETTINGS = {
    "size", "sizes", "value", "values", "command", "commands", "argument", "arguments",
    "arg", "args", "option", "options", "version", "parameter", "parameters", "param",
    "config", "configuration", "setting", "settings", "attribute", "attributes",
    "property", "properties", "flag", "flags",
}
MEASURES = {
    "length", "width", "height", "depth", "thickness", "weight", "density", "temperature",
    "pressure", "frequency", "velocity", "speed", "rate", "distance", "voltage",
    "intensity", "strength", "magnitude", "capacity", "volume",
}
OTHER = {
    "result", "results", "method", "methods", "format", "status", "mode", "source",
    "context", "output", "input", "data", "error", "action", "kind", "category",
    "module", "style", "description", "content", "contents",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().strip("_.-(\\'\"").lower()
    t = prefix.position
    if t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    if any(stem in word for stem in TYPE_STEMS):
        return carry, -0.6
    if word in SETTINGS:
        return carry, -0.35
    if word in MEASURES:
        return carry, -0.18
    if word in OTHER:
        return carry, -0.2
    return carry, 0.0

programs.sol:
"""Sparse local-syntax approximation, not a full vocabulary lookup.

The strongest negative rules recognize unbraced TeX script commands and
underscore-prefixed code names. Font commands and bare carets get smaller
negative values. Initial token runs and underscore divider lines have their
own corrections. State is two recent tokens, a document label, and whether
we are still repeating the initial token; it resets at document boundaries.
"""
READS = ()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev = older = ''
        initial = True
    else:
        _, prev, older, initial = carry
    still_initial = initial and (not prev or (s == prev and '\ufffd' not in s))
