"""Indonesian/Malay context and syllable-like token endings.

Completed words give a decaying language estimate. Nasal and other closed
endings tend negative, especially -ing; short -e and -em/-om fragments
are positive. Indonesian versus English frequency of the word-so-far
strengthens selected endings and supplies a weak context-independent cue.
Connecting words are neutral. Paired middle dots get a separate positive
response. This is a coarse spelling approximation, resetting per document.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

CONNECTORS = set(
    'yang dan di ke dari dengan untuk ini itu karena juga sebagai atau'.split()
)
LANGUAGE_CUES = set(
    'dengan untuk tidak dalam sebagai karena lebih dapat adalah juga oleh '
    'pada kita kamu mereka telah harus sangat tetapi bukan sebuah sudah '
    'serta seperti saya anda bahwa ingin masih hanya tentang memiliki '
    'menjadi'.split()
)
SHARED_WORDS = set('yang dan di ke dari ini itu akan atau ada'.split())
PARTS = re.compile('[A-Za-z]+|[^A-Za-z]+')


def clip(x):
    return max(0.0, min(1.0, x))


@lru_cache(maxsize=32768)
def language_vote(word):
    word = word.lower()
    if word in LANGUAGE_CUES:
        return 1.0
    if word in SHARED_WORDS:
        return 0.35
    if len(word) > 2:
        ind = zipf_frequency(word, 'id')
        eng = zipf_frequency(word, 'en')
        if ind > 5.3 and ind - eng > 2:
            return 0.7
        if eng > 5.3 and eng - ind > 1.5:
            return -0.5
    return 0.0


@lru_cache(maxsize=32768)
def native_word(word):
    ind = zipf_frequency(word.lower(), 'id') if word else 0.0
    eng = zipf_frequency(word.lower(), 'en') if word else 0.0
    return clip((ind - eng - 1) / 2) * clip((ind - 3) / 2)


def syllable_score(token, native):
    w = token.strip().lower()
    if not w or not w.isascii() or not w.isalpha() or w in CONNECTORS:
        return 0.0
    ing = w.endswith('ing')
    value = 0.7 * (len(w) <= 4 and w.endswith('e'))
    value += 0.8 * w.endswith(('em', 'om'))
    value -= 0.6 * w.endswith('ng') + 2.1 * ing
    value -= 0.6 * w.endswith('h')
    value -= 0.9 * w.endswith(('ir', 'ur', 'ul'))
    value -= 1.5 * w.endswith('au')
    value -= 0.3 * w.endswith(('ang', 'ung'))
    value -= native * (
        2.4 * ing + 1.3 * w.endswith(('p', 't'))
        + 1.1 * w.endswith(('um', 'in'))
    )
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        evidence, word = 0.0, ''
    else:
        _, evidence, word = carry
    evidence *= 0.97
    token = prefix.token_strings[-1]
    for part in PARTS.findall(token):
        if part.isascii() and part.isalpha():
            word = (word + part)[-40:]
        elif word:
            evidence = max(0.0, evidence + language_vote(word))
            word = ''
    native = native_word(word)
    confidence = max(clip(evidence - 1.0), 0.3 * native)
    value = confidence * syllable_score(token, native)
    if len(token) >= 2 and not token.strip('·'):
        value = 1.18
    return (doc, evidence, word), float(value)

