    elif tok in MOMENT:
        value = 0.9
    elif tok == ":" and prefix.token_strings[-2:-1] == ("Title",) and "<|endoftext|>" in prefix.token_strings[-3:-2]:
        value = 5.33
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Action-phase cues, especially starting an action.

Predict a strong negative response to Chinese 'begin', weaker responses to
continuation, ending, restarting, and inchoative '起了'.  Traditional '開始'
is weaker in Japanese contexts (recent kana) and in '一開始' ('at first').
In English the largest response is on 'to' after begin/start; continuation
and deciding to act are weaker.  Inflected forms have different strengths.
Vietnamese 'bắt đầu' is another onset cue.  With no prior context or no
matched cue, predict a small background value.  No learned token-ID table
is used, and the short context buffer resets with each document.
"""
import re
import regex
import wordnet

READS = ()

# Other Chinese action-phase words; exact tokens, not arbitrary IDs.
PHASE = {
    '继续': -1.2, '繼續': -0.85,  # continue
    '结束': -1.3, '結束': -0.85,  # finish
    '重新': -0.49,              # again / restart
    '开端': -1.8, '開端': -1.8,  # outset
    '起了': -0.75,              # action comes into being
}
KANA = regex.compile(r'[\p{Script=Hiragana}\p{Script=Katakana}]')
LAST_WORD = re.compile(r'([A-Za-z]+)$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = -0.003
    if old:
        if word == 'to':
            match = LAST_WORD.search(old.rstrip())
            previous = match.group(1).lower() if match else ''
            roots = wordnet.base_forms(previous)
            if 'begin' in roots:
                value = -1.7
            elif 'start' in roots:
                if previous == 'starting':
                    value = -2.6
                elif previous == 'start':
                    value = -0.6
                else:
                    value = -1.35
            elif 'continue' in roots:
                value = -0.43
            elif 'decide' in roots:
                value = -0.62 if previous == 'decided' else -0.24
        elif '开始' in token or '開始' in token:
            if '一开始' in token or '一開始' in token or old.endswith('一'):
                value = -1.65
            elif '开始' in token:
                value = -4.8
            else:
                value = -0.95 if KANA.search(old) else -3.7
        elif token == '始' and old.endswith(('开', '開')):
            value = -4.5
        elif token in PHASE:
            value = PHASE[token]
        elif word == 'đầu' and old.lower().endswith('bắt'):
            value = -1.8
    return (doc, (old + token)[-96:]), value

"""Local lexical responses, not a general semantic classifier.

Strong negative pulses mark a few English continuations of 'just' and
'simply'. Positive pulses mark shortness and selected Chinese/Japanese
words for concrete actuality or distinctive characteristics. Most tokens
receive zero. Negation damps the English response. Repeated middle-dot
separators receive a positive value. Compound endings can cross a token
boundary; documents cannot. Pulse sizes are conservatively reduced because
these local patterns do not determine the activation completely.
"""
import re

READS = ()
NEGATED = re.compile(r"(?:not|n['’]t)\s+(?:just|simply|merely)$")

# These are phrase constructions: cause, purpose, means, comparison,
# approximation, and temporal restriction. Other uses of 'just' stay quiet.
JUST = {
    'because': -5.7, 'for': -4.8, 'to': -4.0, 'from': -6.0,
    'by': -4.8, 'so': -4.2, 'about': -3.2, 'like': -1.7,
    'yet': -6.0, 'now': -2.2, 'when': -0.8,
}
SIMPLY = {'because': -3.7, 'by': -4.8, 'to': -2.1, 'for': -2.4}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    value = 0.0
    if text.startswith(' '):
        if previous == 'just':
            value = JUST.get(word, 0.0)
        elif previous == 'simply':
            value = SIMPLY.get(word, 0.0)
        elif previous == 'merely':
            if word == 'because':
                value = -4.0
            elif word == 'to':
                value = -1.0

    # Negation removes the restrictive reading: 'not just because ...'.
    if NEGATED.search(tail.lower()):
        value *= 0.1

    # Separate, much smaller multilingual lexical responses.
    if text == '短':                         # short / brief
        value = 2.0
    elif text == '短期':
        value = 0.8
    elif text in ('実', '實'):                # actuality / truth
        value = 0.55
    elif text == '特':                        # special / particular
        value = 0.35
    elif text == '自身':                      # oneself
        value = 1.0
    elif text.lstrip('的') in ('具体', '具體', '具体的'):
        value = 0.65
    elif text in ('实际', '實際'):
        value = 1.0
    elif text in ('实际情况', '實際情況', '实效', '實效'):
        value = 2.2
    elif text.lstrip('的') in ('特色', '特点', '特點', '特征', '特徵', '特徴'):
        value = 2.7
    elif previous in ('特', '実', '實'):
        if previous == '特' and text in ('色', '点', '點', '征', '徵', '徴'):
            value = 2.2
        elif previous in ('実', '實') and text in ('際', '情', '態'):
            value = 1.2
    elif text in ('纯', '純') and tail.endswith(('清', '单', '單', '単')):
        value = -1.1
    # Decorative runs of middle dots, rather than an ordinary single dot.
    if len(text) >= 2 and set(text) == {'·'} and tail.endswith('··'):
        value = 1.4
    return (doc, word, (tail + text)[-12:]), 0.75 * value

"""Approximate the component's local ASCII-colon formatting response.

Closing a compact colon-delimited field (time, source location, :role:, or
Markdown alignment dashes) is strongly negative. Spaced labels are weaker.
Indentation after a colon-ended line is positive, with adjustments for Python
block headers and comments. Digits after numeric colons are negative, especially
zero padding. A small explicit case covers ``: public`` inheritance clauses.
Most ordinary text gets zero; token-specific continuation effects are omitted.
The state remembers the latest colon and current line, and resets per document.
"""
import math
import re

READS = ()
BLOCK_HEADER = re.compile(
    r'(?:async\s+)?(def|class|if|elif|else|for|while|'
    r'try|except|finally|with)\b'
)


def closing_colon(text, colon, body, age):
    field = body.strip()
    compact = body.isascii() and body.replace('_', '').isalnum()
    dashes = bool(body) and not body.strip('-')
    numeric_decay = min(1.0, (2 / max(1, age - 1)) ** .7)
    if field and (compact or dashes):
        if field.isdigit():
            response = 9.5 * numeric_decay
        else:
            response = 10.0 * math.exp(-.15 * max(0, age - 4))
    elif field and field.isdigit() and '\n' not in body:
        response = 5.5 * numeric_decay
    else:
        response = 6.0 * math.exp(-.5 * max(0, age - 1))
        if any(c in body for c in '/,()[]{}@=-'):
            response *= .15
    if '\n' in colon or '\r' in colon:
        response *= .22
    elif colon.strip() not in (':', '：'):
        response *= .55
    if '\n' in body or '\r' in body:
        response *= .2
    clean = text.strip()
    # Namespace operators, URLs, and attached punctuation are weaker.
    if '::' in clean:
        response *= .03
    elif '//' in clean or not clean.startswith(':'):
        response *= .08
    elif len(clean) > 1:
        response *= .4
    if text.startswith(' ') and not field.isdigit():
        response *= .65
    return -response


def indentation(text, colon, body, age, header):
    width = len(text.expandtabs(4))
    if not width or not any(c in colon + body for c in '\r\n'):
        return 0.0
    value = .8 + .6 * math.log(width)
    value += .5 * (width % 4 == 3 and header != 'other')
    value = min(value, 2.9)
    if width >= 3:
        if header in ('else', 'except', 'finally'):
            value += 1.5 if header == 'except' else 1.0
        elif header in ('for', 'while'):
            value += .6
    if header == 'comment':
        value *= .2
    if '\t' in text:
        value = 2.3 if text.count('\t') <= 2 else 1.1
    value *= .5 ** max(0, age - 1 - body.count('\n'))
    value *= .4 ** max(0, (colon + body).count('\n') - 1)
    return value


def predict(carry, text, doc):
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 99, '', False, 0.0, '', '')
    _, colon, body, age, previous, numeric, colon_value, line, header = carry
    age += 1
    value = 0.0
    if colon and age <= 24:
        if ':' in text:
            value = closing_colon(text, colon, body, age)
        elif (text.isspace() and not body.strip()
              and '\n' not in text and '\r' not in text):
            value = indentation(text, colon, body, age, header)
        elif text.isdigit() and colon.strip() == ':':
            boost = 1 + min(1.5, abs(colon_value) / 10)
            if not body:
                value = -((.7 + .6 * (text == '0')) if numeric else .1)
            elif body.isdigit() and len(body) == 1:
                value = -((.15 + .5 * (text == '0')) if numeric else .02)
            value *= boost
        elif not body and colon.strip() == ':' and text == ' public':
            value = 6.5
    new_line = (line + text).split('\n')[-1][-256:]
    if ':' in text:
        at = text.rfind(':')
        before = (line + text[:at]).split('\n')[-1]
        before = re.sub(r'^\s*(?:\d+\s+)?', '', before)
        match = BLOCK_HEADER.match(before)
        header = match.group(1) if match else 'other'
        if before.startswith(('#', '//')):
            header = 'comment'
        # Newlines attached to the colon stay in its token, not in body.
        carry = (doc, text, text[at+1:].strip('\r\n'), 0, text,
                 previous.isdigit(), value, new_line, header)
    else:
        carry = (doc, colon, (body + text)[-256:], age, text, numeric,
                 colon_value, new_line, header)
    return carry, float(value)


def step(carry, prefix, upstream):
    return predict(carry, prefix.token_strings[-1], prefix.document_ids[-1])

programs.haiku:
"""Second colon in a whitespace-free chain like 09:00:00, file.rs:114:30, aws:deploy:x."""
READS = ()


def _run_before(strs):
    # The whitespace-free text just before the last token.
    run = ""
    for piece in reversed(strs[:-1]):
        if any(ch.isspace() for ch in piece):
            return piece[max(i for i, ch in enumerate(piece) if ch.isspace()) + 1:] + run
        run = piece + run
    return run


def step(carry, prefix, upstream):
    s = prefix.token_strings
    if s[-1] != ":":
        return None, 0.0
    run = _run_before(s)
    if ":" not in run or "//" in run:
        return None, 0.0
    digits_only = run.replace(":", "").isdigit()
    return None, -9.0 if digits_only else -6.0

programs.sol:
"""A sparse approximation to negative punctuation responses in run-on prose.

Ellipses mixed with repeated exclamations mark chains of text fragments.
Punctuation cutting off an article, preposition or conjunction strengthens
the response. Newlines suppress this heuristic; document boundaries reset it.
At document starts a separate shape bias uses case, length and whitespace.
Elsewhere ordinary tokens receive a near-zero prediction.
"""
READS = ()

INCOMPLETE = frozenset(
    'a an the to of in on for with and or but as at by from your their its '
    'my our is are was be that which not'.split()
)


def initial_shape(s):
    """A coarse first-token bias, without memorizing individual words."""
    t = s.strip()
    if s.isspace():
        return -0.02 if '\n' in s else -0.22
    if t.isdecimal():
        return -0.11
    if t.isascii() and t.isalpha():
        return (0.035 + 0.13 * min(len(t), 12) / 12
                - 0.06 * t.islower() + 0.035 * t.istitle()
                - 0.18 * t.isupper() + 0.03 * s.startswith(' '))
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        carry = (doc, 0, 0, 0, False, '')
    _, bangs, dots, odd, newline, word = carry
    s = prefix.token_strings[-1]
    bang = s in ('!', '.!', ':!', ',!')
    ellipsis = 2 <= len(s) <= 4 and set(s) == {'.'}
    unfinished = word.lower() in INCOMPLETE
    value = -0.0015

    if not newline:
        if bang:
            if dots >= 2:
                value = (-0.8 if bangs >= 4 else -0.6) - 0.2 * unfinished
            elif dots:
                value = -0.35 - 0.2 * unfinished
            elif unfinished:
                value = -0.5 if odd else -0.25
            if len(s) > 1:
                value = min(value, -0.4) - 0.15 * (dots > 0)
        elif ellipsis:
            if bangs >= 2:
                value = (-0.65 if bangs >= 4 else -0.45) - 0.1 * unfinished
            elif bangs and dots:
                value = -0.3 - 0.2 * unfinished
        elif s == '.' and dots >= 3 and bangs >= 2:
            value = -0.15 - 0.25 * unfinished
        elif s == ',.' and bangs and dots:
            value = -0.65

    if (bang or ellipsis or s == '.') and unfinished:
        odd += 1
    bangs += bang
    dots += ellipsis
    newline = newline or '\n' in s
    if first:
        value = initial_shape(s)
    # Keep the last letter-run, joining word pieces across token boundaries.
    for ch in s:
        word = (word + ch)[-16:] if ch.isalpha() else ''
    return (doc, bangs, dots, odd, newline, word), value

"""A sparse detector of quantity notation and local complement phrases.

Percent and degree notation give negative responses. Percent signs used in
URLs or template delimiters are different. English responses depend on the
preceding word: especially 'reason to', 'with respect', and evaluative
adjectives followed by 'to'. A few literal Chinese character responses are
also included, along with the colon in a document-title header.
Unmatched tokens predict zero, not a full lexical lookup.
Only the last 256 characters are retained, resetting at document boundaries.
"""
import re

READS = ()

# Classes of words which can introduce an infinitive.
OPPORTUNITY = set('chance opportunity ability capacity permission right freedom '
                  'means'.split())
EVALUATION = set('possible impossible easy difficult hard useful helpful good '
                 'better best natural likely unlikely allowed required ready '
                 'willing able unable interesting'.split())
JUDGMENT = set('sufficient fair correct appropriate obvious straightforward'.split())
SAFETY = {'safe', 'safer', 'reasonable', 'convenient', 'logical'}
TIME_OR_GROUNDS = {'time', 'occasion', 'room', 'cause', 'proof', 'evidence'}
INDEFINITE = {'nothing', 'something', 'anything', 'little', 'much'}
COMPLETION = set('replaced filled covered marked finished complete enclosed '
                 'bordered surrounded combined mixed multiplied divided'.split())
COMPARISON = {'same', 'identical', 'similar', 'accompanied'}
DEDUCTION = {'follows', 'holds', 'obtain', 'obtains', 'get', 'gets', 'give', 'gives'}
POSSESSION = {'have', 'has', 'had', 'having', 'without', 'no'}


def response(token, before):
    word = token.strip().lower()
    match = re.search(r'([a-zA-Z]+)\s*$', before)
    previous = match[1].lower() if match else ''
    numeric = bool(re.search(r'\d\s*$', before))
    if word in {'{%', '}%'}:
        return 2.5
    if word.startswith(('%', '％')):
        segment = before.rsplit(None, 1)[-1] if before.strip() else ''
        if token == '%' and ('://' in segment or 'www.' in segment):
            return 1.2
        if before.endswith('{'):
            return 2.5
        if re.search(r'\d\\$', before):
            return -4.5
        if numeric or previous in {'hundred', 'thousand', 'mol'}:
            if token[0].isspace():
                return -1.8
            if word[1:].startswith(')'):
                return -1.9
            if word[1:].startswith(','):
                return -1.5
            if word[1:].startswith('.'):
                return -0.85
            if '\n' in token:
                return -1.6
            match = re.search(r'\d+(?:[.,]\d+)?\s*$', before)
            number = float(match[0].replace(',', '.')) if match else None
            if number == 100:
                return -1.9
            if number is not None and number.is_integer() and 0 <= number < 10:
                return -2.5
            if number is not None and 10 <= number < 100 and number % 10 == 0:
                return -3.7
            return -3.1
    if word in {'percent', 'percentage', 'percentages'}:
        return -0.95
    if word in {'°', '℃', '℉'}:
        return -2.2
    if word in {'degree', 'degrees', '-degree'} and numeric:
        return -1.25
    if word == 'circ' and before.endswith('^\\'):
        return -4.1 if re.search(r'\d\^\\$', before) else -1.7
    if token == '^\\' and numeric:
        return -2.5
    if word == 'respect' and previous == 'with':
        math = re.search(r'[$\\]|\b(derivative|integral|vector|equation)\b', before)
        return -4.8 if math else -2.4
    if word == 'to':
        if previous in {'respect', 'reference'}:
            return -1.1
        if previous in {'reason', 'reasons'}:
            return -7.1
        if previous in SAFETY:
            return -3.0
        if previous in INDEFINITE or previous in TIME_OR_GROUNDS:
            return -1.2
        if previous in {'way', 'ways'}:
            return -0.3
        if previous in OPPORTUNITY:
            return -0.45
        if previous in {'necessary', 'essential', 'important'}:
            return -0.65
        if previous in JUDGMENT:
            return -1.4
        if previous in EVALUATION:
            return -0.3
        if previous == 'enough':
            return -1.0
        if previous in {'appears', 'waiting', 'takes'}:
            return -0.6
    if word == 'with':
        if previous in COMPARISON:
            return 2.3
        if previous in COMPLETION:
            return 0.25
    if word == 'that':
        if previous in DEDUCTION:
            return -1.0
        if previous in {'have', 'has', 'had'}:
            return -2.0
    if previous in POSSESSION:
        if word == 'access':
            return -1.65
        if word == 'reason':
            return -2.3
        if word == 'evidence':
            return -0.9
    if word in {'飯', '饭'}:  # rice / a meal
        return -5.5
    if word == '理' and before.endswith(('無', '无', '没')):
        return -6.5
    if token == ':' and re.search(r'(^|<\|endoftext\|>)Title$', before):
        return -4.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, (before + token)[-256:]), response(token, before)
